let currentRole = ROLES.admin;

function hasPermission(permissionCode) {
  if (!currentRole) return false;
  if (currentRole.id === 'admin') return true;
  return Array.isArray(currentRole.permissions) && currentRole.permissions.includes(permissionCode);
}

function getAvailableRoles() {
  return Object.values(ROLES);
}

function saveCustomRole(roleData) {
  if (!roleData || (!roleData.name && !roleData.id) || !roleData.roleTitle) {
    showToast('El identificador del rol y el título son obligatorios.', 'error');
    return false;
  }
  const id = (roleData.id || roleData.name.toLowerCase().replace(/[^a-z0-9_]/g, '_')).trim();
  const isExisting = Boolean(ROLES[id]);
  const isSystem = isExisting && ROLES[id].isSystem;

  ROLES[id] = {
    id: id,
    name: roleData.operatorName || (isExisting ? ROLES[id].name : roleData.roleTitle),
    avatar: roleData.avatar || (isExisting ? ROLES[id].avatar : roleData.roleTitle.substring(0, 2).toUpperCase()),
    roleTitle: roleData.roleTitle,
    isExecutive: Boolean(roleData.isExecutive),
    isSystem: isSystem,
    description: roleData.description || 'Perfil operativo personalizado.',
    allowedHubs: Array.isArray(roleData.allowedHubs) ? roleData.allowedHubs : ['dashboard'],
    permissions: Array.isArray(roleData.permissions) ? roleData.permissions : []
  };

  if (currentRole && currentRole.id === id) {
    currentRole = ROLES[id];
    updateRoleUI();
  }

  showToast(`Rol "${ROLES[id].roleTitle}" guardado exitosamente.`);
  return ROLES[id];
}

function deleteCustomRole(roleId) {
  const role = ROLES[roleId];
  if (!role) {
    showToast('El rol no existe.', 'error');
    return false;
  }
  if (role.isSystem || ['admin', 'warehouse', 'sales', 'finance', 'vendor', 'packer', 'purchases', 'all_roles'].includes(roleId)) {
    showToast('Los roles base del sistema son inmutables y no pueden eliminarse.', 'error');
    return false;
  }

  delete ROLES[roleId];

  if (currentRole && currentRole.id === roleId) {
    currentRole = ROLES.warehouse;
    updateRoleUI();
  }

  showToast('Rol personalizado eliminado.');
  return true;
}

function getAllowedTaskCategoriesForRole(roleId) {
  if (roleId === 'purchases') {
    return ['recepcion', 'compras'];
  }
  if (roleId === 'packer') {
    return ['empaque', 'expedicion'];
  }
  return ['empaque', 'recepcion', 'surtido', 'expedicion', 'compras'];
}

