function validateAddressPredictive(addr) {
  if (!addr) {
    return {
      isValid: false,
      score: 0,
      status: 'critical',
      issues: ['No se proporcionaron datos de domicilio.'],
      warnings: [],
      coverage: 'unknown',
      suggestedColonias: [],
      message: 'Domicilio vacio.'
    };
  }

  const street = (addr.street || '').trim();
  const extNumber = (addr.extNumber || '').trim();
  const postalCode = (addr.postalCode || '').trim();
  const colonia = (addr.colonia || '').trim();
  const municipality = (addr.municipality || '').trim();
  const state = (addr.state || '').trim();

  const issues = [];
  const warnings = [];
  let score = 100;

  // 1. Validar nombre de calle
  if (!street) {
    issues.push('Falta nombre de calle o avenida principal.');
    score -= 30;
  }

  // 2. Validar numero exterior
  const invalidExtRegex = /^(s\/?n|sin\s+n[uú]mero|conocido|domicilio\s+conocido)$/i;
  if (!extNumber) {
    issues.push('Numero exterior obligatorio faltante para emision de guia oficial.');
    score -= 40;
  } else if (invalidExtRegex.test(extNumber)) {
    issues.push('Numero exterior ambiguo ("' + extNumber + '"). DHL requiere numeracion formal.');
    score -= 40;
  }

  // 3. Validar sintaxis y catalogo de Codigo Postal
  let catalogEntry = null;
  if (!postalCode) {
    issues.push('Codigo postal ausente.');
    score -= 40;
  } else if (!/^\d{5}$/.test(postalCode)) {
    issues.push('Codigo postal invalido: debe contener exactamente 5 digitos numericos.');
    score -= 40;
  } else {
    catalogEntry = SEPOMEX_CATALOG[postalCode];
    if (!catalogEntry) {
      warnings.push('Codigo postal no indexado en cache local Sepomex. Se cotejara en linea.');
      score -= 10;
    }
  }

  let coverage = 'standard';
  let courierNote = 'DHL Express Cobertura Nacional Garantizada';
  let suggestedColonias = [];

  if (catalogEntry) {
    coverage = catalogEntry.coverage || 'standard';
    courierNote = catalogEntry.courierNote || 'DHL Express Cobertura Confirmada';
    suggestedColonias = catalogEntry.colonias || [];

    if (coverage === 'extended_zone') {
      warnings.push('Codigo postal en Zona Extendida: aplica cargo y tiempo de reexpedicion (+48h).');
      score -= 10;
    }

    // Cruce de colonia
    if (colonia && suggestedColonias.length > 0) {
      const norm = (s) => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
      const match = suggestedColonias.some(c => norm(c) === norm(colonia));
      if (!match) {
        warnings.push(`Colonia "${colonia}" no registrada en el catalogo oficial del CP ${postalCode}.`);
        score -= 15;
      }
    } else if (!colonia) {
      issues.push('Colonia o asentamiento no especificado.');
      score -= 20;
    }
  }

  score = Math.max(0, Math.min(100, score));

  let status = 'valid';
  if (issues.length > 0 || score < 60) {
    status = 'critical';
  } else if (warnings.length > 0 || score < 90) {
    status = 'warning';
  }

  const isValid = status !== 'critical';

  let message = 'Domicilio validado con exito ante Sepomex y DHL Express.';
  if (status === 'critical') {
    message = issues[0] || 'Domicilio con inconsistencias criticas.';
  } else if (status === 'warning') {
    message = warnings[0] || 'Domicilio con observaciones de cobertura o nomenclatura.';
  }

  return {
    isValid,
    score,
    status,
    issues,
    warnings,
    coverage,
    courierNote,
    suggestedColonias,
    catalogEntry,
    message
  };
}

let activeDashboardTab = 'executive';
let activeExecutiveSubTab = 'revops'; // 'revops' | 'inventory' | 'store' | 'crm' | 'finance' | 'logistics' | 'allies'
let executiveInventoryTimeRange = '30d';

function canAccessDashboardTab(tab) {
  if (!currentRole) return false;
  if (currentRole.id === 'admin' || currentRole.id === 'all_roles') return true;
  if (tab === 'executive') {
    return !!currentRole.isExecutive || hasPermission('dashboard.view_executive');
  }
  if (tab === 'operative') {
    return hasPermission('dashboard.view_operative') || !currentRole.isExecutive;
  }
  if (tab === 'sales') {
    return currentRole.id === 'sales' || hasPermission('marketing.manage_coupons') || hasPermission('marketing.view_ads');
  }
  return false;
}

function getEffectiveDashboardTab() {
  if (currentRole.id === 'warehouse') return 'operative';
  if (currentRole.id === 'sales') return 'sales';
  if (currentRole.id === 'warehouse' || currentRole.id === 'packer' || currentRole.id === 'purchases' || (!currentRole.isExecutive && currentRole.id !== 'admin' && currentRole.id !== 'all_roles')) {
    return 'operative';
  }
  if (activeDashboardTab === 'executive' && !canAccessDashboardTab('executive')) {
    return 'operative';
  }
  if (activeDashboardTab === 'sales' && !canAccessDashboardTab('sales')) {
    return 'operative';
  }
  return activeDashboardTab || 'executive';
}

