function dispatchOperationalEvent(eventType, payload = {}) {
  let newTask = null;

  if (eventType === 'order.paid') {
    const orderId = payload.orderId || `#ORD-${Math.floor(1000 + Math.random() * 9000)}`;
    const customer = payload.customer || 'Cliente Flash';
    const city = payload.city || 'CDMX';
    const courier = payload.courier || 'DHL Express';
    const items = payload.items || [
      { id: `dyn-item-${Date.now()}-1`, name: 'Boxer Pima Organico Blanco - Talla G', sku: 'BOX-PIM-002-G', source: 'Almacen Local (Pasillo A-01)', qty: 1, checked: true },
      { id: `dyn-item-${Date.now()}-2`, name: 'Bolsa de Lavado Delicada', sku: 'ACC-BAG-001', source: 'Cortesia Terra (Promocion)', qty: 1, checked: true }
    ];
    const urgency = payload.urgency || 'Urgente';

    newTask = {
      id: `task-pack-${Date.now()}`,
      category: 'empaque',
      badgeClass: 'urgent',
      badgeText: urgency,
      sla: {
        triggeredAt: getFormattedTime(),
        elapsedHours: 0.3,
        dueTime: '13:30 hrs',
        status: 'ontime',
        label: 'SLA: 18m (En tiempo)'
      },
      title: `Empacar Pedido Confirmado ${orderId}`,
      desc: `Pago confirmado via pasarela. Preparar y sellar paquete para despacho prioritario.`,
      meta: `Cliente: ${customer} • ${city} • Servicio: ${courier}`,
      detail: `Cliente: ${customer} • ${city} • Servicio: ${courier}`,
      actionKey: 'open-pack-mix',
      actionLabel: 'Empacar Pedido',
      status: 'pending',
      data: {
        orderId: orderId,
        customer: customer,
        city: city,
        courier: courier,
        items: items
      }
    };
    operationalState.kpis.pendingPacking = (operationalState.kpis.pendingPacking || 0) + 1;
    showToast(`Nueva tarea generada: Empaque de orden ${orderId} (${customer})`);
  } else if (eventType === 'supplier.shipment_arrived') {
    const ocId = payload.ocId || `#OC-2026-${String(Math.floor(4 + Math.random() * 90)).padStart(3, '0')}`;
    const supplier = payload.supplier || 'Torzo B2B Mayorista';
    const totalQty = payload.totalQty || 80;
    const product = payload.product || 'Jockstrap Athletic Carbon (Curva CH-2XG)';
    const breakdown = payload.breakdown || 'CH: 15 | M: 30 | G: 20 | XG: 10 | 2XG: 5';
    const sealNumber = payload.sealNumber || `SEAL-MX-${Math.floor(10000 + Math.random() * 90000)}`;

    newTask = {
      id: `task-inbound-${Date.now()}`,
      category: 'recepcion',
      badgeClass: 'inbound',
      badgeText: 'Recepcion',
      title: `Recepcion de Carga Mayorista: Orden ${ocId}`,
      desc: `Lote de ${totalQty} piezas recibido en rampa. Cotejar sello inviolable y curva de tallas en Kardex.`,
      meta: `Proveedor: ${supplier} • Total: ${totalQty} uds • Sello: ${sealNumber}`,
      detail: `Proveedor: ${supplier} • Total: ${totalQty} uds • Sello: ${sealNumber}`,
      actionKey: 'open-inbound',
      actionLabel: 'Registrar Entrada',
      status: 'pending',
      data: {
        ocId: ocId,
        supplier: supplier,
        totalQty: totalQty,
        product: product,
        breakdown: breakdown,
        sealNumber: sealNumber,
        checks: [
          { id: `chk-seal-${Date.now()}`, label: `Sello de seguridad intacto en bulto maestro (${sealNumber})`, checked: true },
          { id: `chk-qty-${Date.now()}`, label: `Conteo fisico coincide con albaran (${totalQty} piezas)`, checked: true },
          { id: `chk-curve-${Date.now()}`, label: `Curva de tallas auditada y conforme`, checked: true }
        ]
      }
    };
    operationalState.kpis.inboundTransit = (operationalState.kpis.inboundTransit || 0) + 1;
    showToast(`Nueva tarea generada: Recepcion ${ocId} de ${supplier}`);
  } else if (eventType === 'vendor.shipment_dispatched') {
    const order = payload.order || {};
    const poCode = order.poCode || payload.poCode || 'OC-2026-088';
    const supplierName = order.supplierName || payload.supplierName || 'Torzo Labs & Textile Co.';
    const carrierName = payload.carrierName || order.carrierName || 'Fletera Potosinos Express';
    const trackingNumber = payload.trackingNumber || order.trackingNumber || 'POT-8831920';
    const remissionNumber = payload.remissionNumber || order.remissionNumber || 'REM-4491';
    const totalPieces = order.totalPieces || payload.totalPieces || 150;
    const productName = order.productName || payload.productName || 'Bóxer Ergonómico Modal & Spandex Microfibra';
    const sku = order.sku || payload.sku || 'TRZ-BOXER-NEO';
    const unitCostMxn = order.unitCostMxn || payload.unitCostMxn || 150.00;
    const totalAmountMxn = order.totalAmountMxn || payload.totalAmountMxn || (totalPieces * unitCostMxn);
    const sizes = order.sizes || payload.sizes || { CH: 25, M: 50, G: 50, XL: 25 };

    newTask = {
      id: `task-dock-${poCode.toLowerCase().replace(/[^a-z0-9]/g, '-')}`,
      category: 'recepcion',
      badgeClass: 'urgent',
      badgeText: 'Llegada Fletera',
      sla: {
        triggeredAt: getFormattedTime(),
        dueTime: '14:00 hrs',
        status: 'warning',
        label: 'Rampa Central'
      },
      title: `Llegada Prevista Fletera: Remisión ${remissionNumber} de Torzo Labs (${carrierName})`,
      desc: `Orden ${poCode} (${totalPieces} piezas). Fletera reporta entrega en rampa. Realizar conteo ciego y control de calidad.`,
      meta: `Guía: ${trackingNumber} • Remisión: ${remissionNumber} • ${carrierName}`,
      detail: `Guía: ${trackingNumber} • Remisión: ${remissionNumber} • ${carrierName}`,
      actionKey: 'open-ramp-dock',
      actionLabel: 'Recibir en Rampa',
      status: 'pending',
      data: {
        poCode: poCode,
        supplierName: supplierName,
        carrierName: carrierName,
        trackingNumber: trackingNumber,
        remissionNumber: remissionNumber,
        totalPieces: totalPieces,
        productName: productName,
        sku: sku,
        sizes: sizes,
        unitCostMxn: unitCostMxn,
        totalAmountMxn: totalAmountMxn
      }
    };
    operationalState.kpis.inboundTransit = (operationalState.kpis.inboundTransit || 0) + 1;
    showToast(`Aviso Rampa: Remisión ${remissionNumber} de ${carrierName} precargada en Action Center.`);
  } else if (eventType === 'bom.procurement_orders_generated') {
    const orders = payload.orders || [];
    const batchRef = payload.batchReference || 'SUB-BATCH-2026-09A';
    const bundleSku = payload.bundleSku || 'SUB-BOX-MARTE-LVL2';
    const poCodes = orders.map(o => o.poCode).join(', ');
    const totalPieces = orders.reduce((acc, o) => acc + (o.totalPieces || 0), 0);

    newTask = {
      id: `task-bom-batch-${Date.now()}`,
      category: 'recepcion',
      badgeClass: 'urgent',
      badgeText: 'Deficit BOM',
      sla: {
        triggeredAt: getFormattedTime(),
        dueTime: '18:00 hrs',
        status: 'warning',
        label: 'Seguimiento Maquila'
      },
      title: `Monitoreo Lote BOM: ${orders.length} OCs Despachadas a Extranet (${poCodes})`,
      desc: `Lote de reposicion (${batchRef}) para ${totalPieces} piezas requeridas en ensamble de ${bundleSku}. Monitorear confirmacion de talleres.`,
      meta: `Ordenes: ${poCodes} • Piezas: ${totalPieces} • Ref: ${batchRef}`,
      detail: `Ordenes: ${poCodes} • Piezas: ${totalPieces} • Ref: ${batchRef}`,
      actionKey: 'open-ramp-dock',
      actionLabel: 'Ver en Extranet B2B',
      status: 'pending',
      data: {
        batchReference: batchRef,
        bundleSku: bundleSku,
        orders: orders,
        checks: [
          { id: `chk-bom-taller-${Date.now()}`, label: 'Confirmacion y aceptacion de taller en Extranet B2B', checked: false },
          { id: `chk-bom-rampa-${Date.now()}`, label: 'Validacion de fecha compromiso de arribo a Rampa Central', checked: false }
        ]
      }
    };
    showToast(`Deficit BOM: ${orders.length} OCs inyectadas en Extranet B2B.`);
  } else if (eventType === 'inventory.rop_breached') {
    const sku = payload.sku || 'BOX-MOD-002-G';
    const product = payload.product || 'Boxer Modal Azul Marino - Talla G';
    const fromLoc = payload.fromLoc || 'Rack de Reserva R-04 (Nivel 3)';
    const toLoc = payload.toLoc || 'Anaquel de Picking A-01';
    const unitsToMove = payload.unitsToMove || 15;

    newTask = {
      id: `task-restock-${Date.now()}`,
      category: 'surtido',
      badgeClass: 'stock',
      badgeText: 'Surtido',
      title: `Surtido de Anaquel: Quiebre ROP en ${toLoc}`,
      desc: `Existencia bajo nivel minimo de seguridad. Trasladar ${unitsToMove} unidades desde reserva.`,
      meta: `SKU: ${sku} • Origen: ${fromLoc} • Destino: ${toLoc}`,
      detail: `SKU: ${sku} • Origen: ${fromLoc} • Destino: ${toLoc}`,
      actionKey: 'open-restock',
      actionLabel: 'Marcar Surtido',
      status: 'pending',
      data: {
        sku: sku,
        product: product,
        fromLoc: fromLoc,
        toLoc: toLoc,
        unitsToMove: unitsToMove,
        checks: [
          { id: `chk-move-${Date.now()}`, label: `${unitsToMove} unidades trasladadas desde ${fromLoc} a ${toLoc}`, checked: true },
          { id: `chk-scan-${Date.now()}`, label: 'Lectura de codigo de barras de anaquel confirmada', checked: true }
        ]
      }
    };
    operationalState.kpis.ropBreaks = (operationalState.kpis.ropBreaks || 0) + 1;
    showToast(`Nueva tarea generada: Quiebre ROP en ${toLoc} (${sku})`);
  } else if (eventType === 'shipping.batch_ready') {
    const courier = payload.courier || 'DHL Express';
    const packageCount = payload.packageCount || 8;
    const destinationSummary = payload.destinationSummary || 'CDMX (4), Monterrey (2), Guadalajara (2)';

    newTask = {
      id: `task-shipping-${Date.now()}`,
      category: 'expedicion',
      badgeClass: 'shipping',
      badgeText: 'Expedicion',
      title: `Despacho de Lote Vespertino: ${courier}`,
      desc: `${packageCount} paquetes rotulados y listos para recoleccion y firma de manifiesto.`,
      meta: `Transportista: ${courier} • ${packageCount} bultos • Salida 14:00 hrs`,
      detail: `Transportista: ${courier} • ${packageCount} bultos • Salida 14:00 hrs`,
      actionKey: 'open-shipping',
      actionLabel: 'Emitir Guias',
      status: 'pending',
      data: {
        courier: courier,
        pickupTime: payload.pickupTime || '14:00 hrs',
        packageCount: packageCount,
        destinationSummary: destinationSummary,
        checks: [
          { id: `chk-ship-${Date.now()}`, label: `Etiquetas termicas validadas en ${packageCount} paquetes`, checked: true },
          { id: `chk-man-${Date.now()}`, label: 'Manifiesto de recoleccion firmado por transportista', checked: true }
        ]
      }
    };
    showToast(`Nueva tarea generada: Lote de expedicion ${courier}`);
  }

  if (newTask) {
    operationalState.tasks.unshift(newTask);
    const activeLink = document.querySelector('.module-link.active');
    if (activeLink && activeLink.dataset.screen === 'dashboard') {
      render('dashboard');
    }
  }
  return newTask;
}

