// Generador de Curva SVG Interactiva (Facturacion vs MRR)
function generateSvgRevenueChart(scale = '30d') {
  const data = aiCopilotState.chartData[scale] || aiCopilotState.chartData['30d'];
  const width = 480;
  const height = 140;
  const paddingX = 40;
  const paddingY = 20;

  const maxVal = Math.max(...data.revenue, ...data.mrr) * 1.15;
  const minVal = 0;

  const getX = (idx) => paddingX + (idx / (data.labels.length - 1)) * (width - paddingX * 2);
  const getY = (val) => height - paddingY - ((val - minVal) / (maxVal - minVal)) * (height - paddingY * 2);

  const revPoints = data.revenue.map((v, i) => `${getX(i)},${getY(v)}`).join(' ');
  const mrrPoints = data.mrr.map((v, i) => `${getX(i)},${getY(v)}`).join(' ');

  const areaRevPoints = `${getX(0)},${height - paddingY} ${revPoints} ${getX(data.revenue.length - 1)},${height - paddingY}`;

  return `
    <svg viewBox="0 0 ${width} ${height}" class="w-full h-full overflow-visible" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <linearGradient id="gradRev" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stop-color="#4f46e5" stop-opacity="0.25"/>
          <stop offset="100%" stop-color="#4f46e5" stop-opacity="0.0"/>
        </linearGradient>
      </defs>

      <!-- Lineas de Guia Horizontales -->
      <line x1="${paddingX}" y1="${getY(maxVal * 0.75)}" x2="${width - paddingX}" y2="${getY(maxVal * 0.75)}" stroke="#e2e8f0" stroke-width="1" stroke-dasharray="3 3"/>
      <line x1="${paddingX}" y1="${getY(maxVal * 0.4)}" x2="${width - paddingX}" y2="${getY(maxVal * 0.4)}" stroke="#e2e8f0" stroke-width="1" stroke-dasharray="3 3"/>
      <line x1="${paddingX}" y1="${height - paddingY}" x2="${width - paddingX}" y2="${height - paddingY}" stroke="#cbd5e1" stroke-width="1"/>

      <!-- Area Sombreada de Facturacion -->
      <polygon points="${areaRevPoints}" fill="url(#gradRev)" />

      <!-- Curva de Facturacion -->
      <polyline points="${revPoints}" fill="none" stroke="#4f46e5" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>

      <!-- Curva de MRR -->
      <polyline points="${mrrPoints}" fill="none" stroke="#9333ea" stroke-width="2" stroke-dasharray="4 4" stroke-linecap="round" stroke-linejoin="round"/>

      <!-- Puntos de Facturacion -->
      ${data.revenue.map((v, i) => `
        <circle cx="${getX(i)}" cy="${getY(v)}" r="3.5" fill="#ffffff" stroke="#4f46e5" stroke-width="2"/>
        <text x="${getX(i)}" y="${height - 4}" font-size="9" fill="#64748b" text-anchor="middle" font-family="sans-serif">${data.labels[i]}</text>
      `).join('')}

      <!-- Puntos de MRR -->
      ${data.mrr.map((v, i) => `
        <circle cx="${getX(i)}" cy="${getY(v)}" r="2.5" fill="#ffffff" stroke="#9333ea" stroke-width="1.5"/>
      `).join('')}
    </svg>
  `;
}

