// Funciones del Chat Estratégico IA
function openCopilotChatDrawer() {
  const container = document.querySelector('[data-copilot-chat-container]');
  if (!container) return;
  container.style.display = 'block';
  aiCopilotState.isChatOpen = true;

  const roleKey = (currentRole.id === 'warehouse') ? 'warehouse' : ((currentRole.id === 'sales') ? 'sales' : ((currentRole.id === 'finance') ? 'finance' : 'admin'));
  const roleLabelEl = document.querySelector('[data-copilot-chat-role-label]');
  if (roleLabelEl && aiCopilotState.roleData[roleKey]) {
    roleLabelEl.textContent = `Contexto: ${aiCopilotState.roleData[roleKey].roleLabel}`;
  }

  renderCopilotChatMessages();
  renderCopilotPromptChips();
}

function closeCopilotChatDrawer() {
  const container = document.querySelector('[data-copilot-chat-container]');
  if (container) container.style.display = 'none';
  aiCopilotState.isChatOpen = false;
}

function renderCopilotChatMessages() {
  const msgContainer = document.querySelector('[data-copilot-chat-messages]');
  if (!msgContainer) return;

  const roleKey = (currentRole.id === 'warehouse') ? 'warehouse' : ((currentRole.id === 'sales') ? 'sales' : ((currentRole.id === 'finance') ? 'finance' : 'admin'));
  const msgs = aiCopilotState.chatHistory[roleKey] || [];

  msgContainer.innerHTML = msgs.map(m => `
    <div class="copilot-msg-bubble ${m.sender}">
      ${m.text}
    </div>
  `).join('');

  msgContainer.scrollTop = msgContainer.scrollHeight;
}

function renderCopilotPromptChips() {
  const chipsContainer = document.querySelector('[data-copilot-prompt-chips]');
  if (!chipsContainer) return;

  const roleKey = (currentRole.id === 'warehouse') ? 'warehouse' : ((currentRole.id === 'sales') ? 'sales' : ((currentRole.id === 'finance') ? 'finance' : 'admin'));
  const prompts = aiCopilotState.roleData[roleKey]?.prompts || [];

  chipsContainer.innerHTML = prompts.map(p => `
    <button type="button" class="copilot-chip" data-copilot-prompt-chip="${p}">
      + ${p}
    </button>
  `).join('');
}

function sendCopilotChatMessage(query) {
  if (!query || !query.trim()) return;
  const roleKey = (currentRole.id === 'warehouse') ? 'warehouse' : ((currentRole.id === 'sales') ? 'sales' : ((currentRole.id === 'finance') ? 'finance' : 'admin'));

  if (!aiCopilotState.chatHistory[roleKey]) {
    aiCopilotState.chatHistory[roleKey] = [];
  }

  // Agregar mensaje del usuario
  aiCopilotState.chatHistory[roleKey].push({
    sender: 'user',
    text: query.trim()
  });

  renderCopilotChatMessages();

  // Respuesta determinista contextual por rol (cero llamadas externas bloqueantes)
  setTimeout(() => {
    let reply = '';
    const qLower = query.toLowerCase();

    if (roleKey === 'warehouse') {
      if (qLower.includes('corte') || qLower.includes('dhl') || qLower.includes('hora')) {
        reply = 'El corte de DHL Express es a las 14:00 hrs. La orden #MIX-1048 requiere empaque inmediato para asegurar la recoleccion.';
      } else if (qLower.includes('rop') || qLower.includes('quiebre') || qLower.includes('stock')) {
        reply = 'El anaquel A-02 tiene 4 piezas restantes de Boxer Modal Negro Talla M. Se requiere traslado de 20 unidades desde el Rack B-04.';
      } else if (qLower.includes('manifiesto') || qLower.includes('estafeta')) {
        reply = 'El manifiesto de Estafeta cuenta con 12 paquetes verificados listos en rampa para firma del operador recolector.';
      } else {
        reply = 'Consulta procesada. Las operaciones de bodega marchan conforme a la ruta de pasillos sin discrepancias criticas.';
      }
    } else if (roleKey === 'sales') {
      if (qLower.includes('carrito') || qLower.includes('abandonado')) {
        reply = 'Hay 12 carritos abandonados hoy ($8,450 MXN). 4 de ellos superan los $1,000 MXN y tienen disponible la plantilla con cupon RETORNO10.';
      } else if (qLower.includes('direccion') || qLower.includes('sepomex') || qLower.includes('postal')) {
        reply = 'Se detectaron 3 pedidos retenidos con CP dudoso. La orden #ORD-991 en Iztacalco fue ajustada con el catalogo oficial Sepomex.';
      } else {
        reply = 'Estrategia comercial activa: la tasa de redencion de cupones se mantiene en 18.5% con excelente respuesta en WhatsApp.';
      }
    } else if (roleKey === 'finance') {
      if (qLower.includes('margen') || qLower.includes('neto') || qLower.includes('real')) {
        reply = 'El margen neto real ponderado es del 57.9% tras deducir $1,024.20 MXN de pasarelas, $712.50 MXN de empaque y $1,980 MXN de fletes.';
      } else if (qLower.includes('mrr') || qLower.includes('suscripcion')) {
        reply = 'El proximo corte proyecta $13,400 MXN en cargos recurrentes con una tasa de exito de cobro del 98.8% en pasarela Stripe.';
      } else {
        reply = 'Auditoria financiera al dia. Los lotes de pago cuadran con el libro diario y las retenciones fiscales de ley.';
      }
    } else {
      // admin
      if (qLower.includes('categoria') || qLower.includes('menor margen')) {
        reply = 'La linea de cuidado personal deja un margen neto del 52.4% debido al flete volumetrico, mientras que la ropa interior alcanza el 68.2%.';
      } else if (qLower.includes('envio gratis') || qLower.includes('1199')) {
        reply = 'Simulacion completada: Establecer envio gratis en $1,199 MXN incrementaria el ticket promedio en +18%, absorbiendo el costo de flete con 2.4 piezas por pedido.';
      } else if (qLower.includes('vitrina') || qLower.includes('marte') || qLower.includes('distribuye')) {
        reply = 'Marte representa el 38.5% de la facturacion, Venus el 29.2%, Terra el 20.1% y Tiresias el 12.2%. Todas descuentan del inventario central.';
      } else {
        reply = 'Ecosistema RevOps operando a capacidad optima con 99.98% de disponibilidad y crecimiento sostenido en membresias recurrentes.';
      }
    }

    aiCopilotState.chatHistory[roleKey].push({
      sender: 'assistant',
      text: reply
    });

    renderCopilotChatMessages();
  }, 180);
}

function executeCopilotRecommendation(recId) {
  let found = null;
  Object.values(aiCopilotState.roleData).forEach(r => {
    const item = r.recommendations.find(rec => rec.id === recId);
    if (item) found = item;
  });

  if (!found) return;
  found.executed = true;

  if (found.actionKey === 'open-pack-mix') {
    if (typeof window.openPackMixModal === 'function') {
      window.openPackMixModal();
    } else {
      showToast('Abriendo mesa de empaque para orden prioritaria #MIX-1048');
    }
  } else if (found.actionKey === 'open-restock') {
    if (typeof window.openRestockModal === 'function') {
      window.openRestockModal();
    } else {
      showToast('Tarea de surtido generada para Anaquel A-02');
    }
  } else if (found.actionKey === 'open-shipping') {
    if (typeof window.openShippingModal === 'function') {
      window.openShippingModal();
    } else {
      showToast('Abriendo manifiesto de expedicion para recoleccion');
    }
  } else if (found.actionKey === 'open-sales-whatsapp') {
    if (typeof window.openSalesWhatsAppModal === 'function') {
      window.openSalesWhatsAppModal('case-2');
    } else {
      showToast('Lanzando WhatsApp tokenizado con 10% OFF a carrito VIP');
    }
  } else if (found.actionKey === 'open-sales-address') {
    if (typeof window.openSalesAddressModal === 'function') {
      window.openSalesAddressModal('case-3');
    } else {
      showToast('Abriendo validador predictivo Sepomex para orden #ORD-991');
    }
  } else if (found.actionKey === 'open-funnel-loyalty') {
    if (typeof window.openFunnelLoyaltyModal === 'function') {
      window.openFunnelLoyaltyModal();
    } else {
      showToast('Beneficio de fidelizacion asignado a suscriptor');
    }
  } else if (found.actionKey === 'copilot-scale-ad') {
    showToast('Presupuesto de campaña Meta Ads escalado +20% exitosamente');
  } else if (found.actionKey === 'copilot-simulate-margin') {
    showToast('Simulacion: Subir umbral a $1,199 MXN proyecta +14% en margen neto');
  } else if (found.actionKey === 'copilot-conciliate-batch') {
    showToast('Lote semanal Stripe $42,500 MXN conciliado exitosamente');
  } else if (found.actionKey === 'copilot-schedule-spei') {
    showToast('SPEI de $18,200 MXN para Taller de Costura programado para el viernes');
  } else if (found.actionKey === 'notif-goto-inventory') {
    if (typeof window.navigateToInventory === 'function') {
      window.navigateToInventory({ tab: 'inventory', ropFilter: 'under_rop', bannerMsg: 'Filtro activo: 4 SKUs bajo Punto de Reorden (ROP)' });
    }
  }

  // Re-renderizar widget para reflejar estado completado
  const activeLink = document.querySelector('.module-link.active');
  if (activeLink && activeLink.dataset.screen === 'dashboard') {
    render('dashboard');
  }
}

