// 5.6. SUB-MODULO LOGISTICA, EXPEDICION & POST-VENTA (HUB 6 - TASK-LOG-01)
function generateBatchBarcodeSvg(text) {
  if (!text) text = 'MAN-000';
  const clean = text.replace(/[^A-Za-z0-9_-]/g, '').toUpperCase();
  let rects = [];
  let x = 10;
  const barHeight = 40;

  rects.push(`<rect x="${x}" y="0" width="2" height="${barHeight}" fill="#0f172a"/>`);
  x += 3;
  rects.push(`<rect x="${x}" y="0" width="1" height="${barHeight}" fill="#0f172a"/>`);
  x += 3;

  for (let i = 0; i < clean.length; i++) {
    const code = clean.charCodeAt(i);
    const w1 = (code % 3) + 1;
    const space1 = ((code >> 1) % 2) + 1;
    const w2 = ((code >> 2) % 3) + 1;
    const space2 = ((code >> 3) % 2) + 1;

    rects.push(`<rect x="${x}" y="0" width="${w1}" height="${barHeight}" fill="#0f172a"/>`);
    x += w1 + space1;
    rects.push(`<rect x="${x}" y="0" width="${w2}" height="${barHeight}" fill="#0f172a"/>`);
    x += w2 + space2;
  }

  rects.push(`<rect x="${x}" y="0" width="2" height="${barHeight}" fill="#0f172a"/>`);
  x += 3;
  rects.push(`<rect x="${x}" y="0" width="3" height="${barHeight}" fill="#0f172a"/>`);
  x += 10;

  return `<svg viewBox="0 0 ${Math.max(x, 180)} 44" class="w-full h-10 block" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">${rects.join('')}</svg>`;
}

function generateQrCodeSvg(text) {
  if (!text) text = 'TRK-000';
  const size = 64;
  let cells = [];
  const matrixSize = 16;
  const cellSize = size / matrixSize;

  let hash = 0;
  for (let i = 0; i < text.length; i++) {
    hash = ((hash << 5) - hash) + text.charCodeAt(i);
    hash |= 0;
  }

  for (let r = 0; r < matrixSize; r++) {
    for (let c = 0; c < matrixSize; c++) {
      const isFinderTL = (r < 4 && c < 4);
      const isFinderTR = (r < 4 && c >= matrixSize - 4);
      const isFinderBL = (r >= matrixSize - 4 && c < 4);
      let fill = false;
      if (isFinderTL || isFinderTR || isFinderBL) {
        if ((r === 0 || r === 3 || c === 0 || c === 3) || (r >= matrixSize - 4 && (r === matrixSize - 4 || r === matrixSize - 1 || c === 0 || c === 3)) || (c >= matrixSize - 4 && (r === 0 || r === 3 || c === matrixSize - 4 || c === matrixSize - 1))) {
          fill = true;
        } else if ((r === 1 && c === 1) || (r === matrixSize - 2 && c === 1) || (r === 1 && c === matrixSize - 2)) {
          fill = true;
        }
      } else {
        fill = (((hash ^ (r * 17 + c * 31)) & 7) < 3);
      }
      if (fill) {
        cells.push(`<rect x="${c * cellSize}" y="${r * cellSize}" width="${cellSize}" height="${cellSize}" fill="#0f172a" />`);
      }
    }
  }

  return `<svg viewBox="0 0 ${size} ${size}" width="${size}" height="${size}" class="block" xmlns="http://www.w3.org/2000/svg">${cells.join('')}</svg>`;
}

