function getCarrierPackageCounts() {
  const packed = logisticsState.packages.filter(p => p.status === 'packed');
  const counts = { all: packed.length, dhl: 0, estafeta: 0, fedex: 0, '99minutos': 0 };
  packed.forEach(p => {
    if (counts[p.carrier] !== undefined) {
      counts[p.carrier]++;
    }
  });
  return counts;
}

function getLogisticsFilteredPackages() {
  let list = logisticsState.packages.filter(p => p.status === 'packed');
  if (logisticsState.selectedCarrierFilter !== 'all') {
    list = list.filter(p => p.carrier === logisticsState.selectedCarrierFilter);
  }
  if (logisticsState.searchQuery && logisticsState.searchQuery.trim()) {
    const q = logisticsState.searchQuery.trim().toLowerCase();
    list = list.filter(p =>
      p.orderNumber.toLowerCase().includes(q) ||
      p.customerName.toLowerCase().includes(q) ||
      p.destinationCity.toLowerCase().includes(q) ||
      p.trackingNumber.toLowerCase().includes(q) ||
      p.destinationZip.includes(q)
    );
  }
  return list;
}

function getSelectedPackagesAnalysis() {
  const selectedIds = Array.from(logisticsState.selectedPackages);
  const selectedList = logisticsState.packages.filter(p => selectedIds.includes(p.id) && p.status === 'packed' && !p.fraudHold);
  if (selectedList.length === 0) {
    return { count: 0, isMixed: false, carrier: null, carrierName: '', totalWeightKg: 0, totalVolumeM3: 0, items: [] };
  }
  const firstCarrier = selectedList[0].carrier;
  const isMixed = selectedList.some(p => p.carrier !== firstCarrier);
  const totalWeightKg = selectedList.reduce((acc, p) => acc + p.weightKg, 0);
  const totalVolumeM3 = selectedList.length * 0.0055;
  return {
    count: selectedList.length,
    isMixed,
    carrier: isMixed ? 'mixed' : firstCarrier,
    carrierName: isMixed ? 'Multiples Transportistas' : selectedList[0].carrierName,
    totalWeightKg: parseFloat(totalWeightKg.toFixed(2)),
    totalVolumeM3: parseFloat(totalVolumeM3.toFixed(4)),
    items: selectedList
  };
}

// 5.6.B. GESTOR CRUD DE CAJAS, EMPAQUES Y VOLUMETRIA (HUB 6 - TASK-LOG-06)
function calculateVolumetricWeight(l, w, h) {
  const len = parseFloat(l) || 0;
  const wid = parseFloat(w) || 0;
  const hgt = parseFloat(h) || 0;
  if (len <= 0 || wid <= 0 || hgt <= 0) return 0;
  return Math.round(((len * wid * hgt) / 5000) * 100) / 100;
}

function calculatePackageMetrics(l, w, h, tareG = 0, costMxn = 0) {
  const len = parseFloat(l) || 0;
  const wid = parseFloat(w) || 0;
  const hgt = parseFloat(h) || 0;
  const tare = parseInt(tareG) || 0;
  const cost = parseFloat(costMxn) || 0;
  const cm3 = Math.round(len * wid * hgt * 100) / 100;
  const dm3 = Math.round((cm3 / 1000) * 100) / 100;
  const m3 = Math.round((cm3 / 1000000) * 10000) / 10000;
  const volKg = calculateVolumetricWeight(len, wid, hgt);
  const tareKg = Math.round((tare / 1000) * 100) / 100;
  return { len, wid, hgt, cm3, dm3, m3, volKg, tareG: tare, tareKg, cost };
}

