function getFilteredPackageTypes() {
  let list = [...(logisticsState.packageTypes || [])];
  if (logisticsState.packagingCategoryFilter && logisticsState.packagingCategoryFilter !== 'all') {
    const f = logisticsState.packagingCategoryFilter;
    list = list.filter(pkg => (pkg.compatibleCategories || []).includes(f));
  }
  if (logisticsState.packagingSearchQuery && logisticsState.packagingSearchQuery.trim() !== '') {
    const q = logisticsState.packagingSearchQuery.toLowerCase().trim();
    list = list.filter(pkg => 
      pkg.code.toLowerCase().includes(q) || 
      pkg.name.toLowerCase().includes(q) || 
      (pkg.description && pkg.description.toLowerCase().includes(q))
    );
  }
  return list;
}

