function executeRmaReplacement(rmaId, variantSku) {
  const idNum = parseInt(rmaId);
  const rma = (logisticsState.rmaRequests || []).find(r => r.id === idNum);
  if (!rma) return;

  const orderFolio = `${rma.orderNumber}-RMA`;
  const nowTime = getFormattedTime();

  // 1. Inyectar en paquetes de Logística
  const newPackage = {
    id: Date.now(),
    orderNumber: orderFolio,
    orderType: 'Reemplazo Garantía RMA',
    customerName: rma.customerName,
    destinationCity: rma.destinationCity || 'CDMX',
    destinationState: rma.destinationState || 'CDMX',
    destinationZip: rma.destinationZip || '08100',
    sepomexVerified: true,
    carrier: rma.returnCarrier === 'DHL Express' ? 'dhl' : (rma.returnCarrier === 'FedEx' ? 'fedex' : 'estafeta'),
    carrierName: rma.returnCarrier || 'Estafeta',
    serviceLevel: 'Garantía Express 24h',
    trackingNumber: `REP-${Date.now().toString().slice(-6)}`,
    weightKg: 0.85,
    dimensions: '25x18x10 cm',
    boxType: 'Caja Nivel 1 Microcorrugado',
    packedAt: nowTime,
    slaStatus: 'ontime',
    status: 'packed',
    manifestId: null,
    fraudRiskScore: 3,
    fraudHold: false,
    fraudDetails: null
  };
  logisticsState.packages.unshift(newPackage);

  // 2. Inyectar tarea operativa en Dashboard (Mesa de Empaque)
  if (operationalState && operationalState.tasks) {
    operationalState.tasks.unshift({
      id: `task-rep-${Date.now()}`,
      category: 'empaque',
      badgeClass: 'urgent',
      badgeText: 'RMA Prioritario',
      addressVerified: true,
      sla: {
        triggeredAt: nowTime,
        elapsedHours: 0.1,
        dueTime: '13:30 hrs',
        status: 'critical',
        label: 'SLA: Prioridad Inmediata'
      },
      title: `Empacar Reemplazo de Garantía ${orderFolio}`,
      desc: `Sustitución aprobada para ${rma.customerName}. SKU: ${variantSku}. Folio RMA: ${rma.rmaFolio}`,
      meta: `Cliente: ${rma.customerName} • ${rma.destinationCity || 'CDMX'} • Servicio: ${newPackage.carrierName}`,
      actionKey: 'open-pack-rma',
      actionLabel: 'Empacar Reemplazo',
      status: 'pending',
      data: {
        orderId: orderFolio,
        packageId: newPackage.id,
        customer: rma.customerName,
        sku: variantSku
      }
    });
    operationalState.kpis.pendingPacking = (operationalState.kpis.pendingPacking || 0) + 1;
  }

  // 3. Asiento inmutable en Kardex
  if (typeof window !== 'undefined') {
    window.inventoryKardex = window.inventoryKardex || [];
    window.inventoryKardex.unshift({
      id: `kardex-rep-${Date.now()}`,
      timestamp: new Date().toISOString(),
      type: 'SALIDA_REEMPLAZO_RMA',
      sku: variantSku,
      quantity: 1,
      reference: orderFolio,
      note: `Salida de almacén por orden de reemplazo RMA ${rma.rmaFolio} a $0.00 MXN`
    });
  }

  // 4. Actualizar estado del RMA
  rma.status = 'replacement_issued';
  rma.resolution = {
    type: 'replacement_order',
    orderNumber: orderFolio,
    sku: variantSku,
    issuedAt: nowTime
  };
  rma.inspectionNotes = (rma.inspectionNotes ? rma.inspectionNotes + ' | ' : '') + `Orden de reemplazo ${orderFolio} generada (${nowTime}).`;

  // 5. Bitácora operacional
  if (operationalState && operationalState.shiftLog) {
    operationalState.shiftLog.unshift({
      id: `shift-log-rep-${Date.now()}`,
      time: nowTime,
      action: `Orden Reemplazo ${orderFolio}`,
      user: 'Mickey RevOps',
      detail: `Generada orden de reemplazo a $0.00 MXN para ${rma.customerName}. SKU: ${variantSku}. Despachada a cola de empaque de Almacén.`,
      type: 'logistica'
    });
  }

  closeActionModal();
  render('logistics');
  showToast(`Orden de reemplazo ${orderFolio} generada y despachada a la cola de empaque.`);
}

