function executeEnvironmentSwitch(targetEnv, confirmationText = '', reason = '', isLiabilityChecked = false) {
  if (targetEnv !== 'sandbox' && targetEnv !== 'production') {
    showToast('Entorno de destino inválido.', 'error');
    return false;
  }

  // 1. Verificación de rol Super Admin
  if (!currentRole || currentRole.id !== 'admin') {
    showToast('Acceso denegado: Solo el Super Admin puede conmutar el entorno.', 'error');
    return false;
  }

  // 2. Reto de doble factor si el destino es Producción
  if (targetEnv === 'production') {
    if (confirmationText.trim().toUpperCase() !== 'PRODUCCION') {
      showToast('Debes transcribir exactamente la palabra PRODUCCION.', 'error');
      return false;
    }
    if (!isLiabilityChecked) {
      showToast('Debes aceptar la casilla de responsabilidad operativa.', 'error');
      return false;
    }
  }

  if (!reason || reason.trim().length < 5) {
    showToast('Debes ingresar un motivo de al menos 5 caracteres para la auditoría.', 'error');
    return false;
  }

  const fromEnv = environmentState.currentEnv;
  const nowStr = getFormattedTime();

  environmentState.currentEnv = targetEnv;
  environmentState.lastSwitchedAt = 'Hoy, ' + nowStr;
  environmentState.lastSwitchedBy = currentRole.name + ' (' + currentRole.roleTitle + ')';

  // Registrar en historial de auditoría de entornos
  environmentState.auditLogs.unshift({
    id: `ENV-LOG-${Date.now()}`,
    timestamp: 'Hoy, ' + nowStr,
    fromEnv: fromEnv,
    toEnv: targetEnv,
    user: currentRole.name,
    role: currentRole.roleTitle,
    securityChallengePassed: targetEnv === 'production' ? 'PRODUCCION_CONFIRMED' : 'SANDBOX_RESET',
    reason: reason.trim(),
    ip: '192.168.1.50'
  });

  // Asentar en bitácora inmutable de turno
  const targetLog = (typeof operationalState !== 'undefined' && operationalState) ? (operationalState.shiftLog || operationalState.completedLog) : null;
  if (targetLog) {
    targetLog.unshift({
      id: `shift-log-env-${Date.now()}`,
      time: nowStr,
      action: 'Conmutación de Entorno',
      user: currentRole.name,
      detail: `Entorno cambiado de ${fromEnv.toUpperCase()} a ${targetEnv.toUpperCase()}. Motivo: ${reason.trim()}.`,
      type: 'seguridad'
    });
  }

  renderEnvironmentIndicator();
  closeActionModal();

  if (targetEnv === 'production') {
    showToast('MODO PRODUCCIÓN ACTIVADO: Operaciones en vivo con fondos y guías reales.', 'info');
  } else {
    showToast('Modo Sandbox activado: Transacciones y guías simuladas ($0 MXN).', 'info');
  }

  return true;
}

