// Acciones Interactivas y de Dominio
function scaleAdCampaign(campaignId) {
  const camp = marketingState.adCampaigns.find(c => c.id === campaignId);
  if (!camp) return false;
  
  const oldBudget = camp.dailyBudget;
  camp.dailyBudget = Math.round(camp.dailyBudget * 1.20);
  const rec = marketingState.growthRecommendations.find(r => r.campaignId === campaignId && r.actionType === 'scale_campaign');
  if (rec) rec.executed = true;

  // Emisión de evento inter-hub para notificación preventiva a empaque (TASK-INT-12)
  if (typeof window !== 'undefined') {
    if (typeof window.dispatchEvent === 'function') {
      window.dispatchEvent(new CustomEvent('ad-budget-scaled', { 
        detail: { 
          campaignId, 
          campaignName: camp.name,
          oldBudget, 
          newBudget: camp.dailyBudget,
          leadSource: 'Meta Ads Flash Surge',
          targetHub: 'logistics'
        } 
      }));
    }
  }

  // Asentar en bitácora de turno operativa si existe
  if (typeof operationalState !== 'undefined' && operationalState && operationalState.shiftLog) {
    operationalState.shiftLog.unshift({
      id: `shift-log-mkt-scale-${Date.now()}`,
      time: (typeof getFormattedTime === 'function') ? getFormattedTime() : new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      action: 'Escalamiento Ads +20% (TASK-INT-12)',
      user: (typeof currentRole !== 'undefined' && currentRole && currentRole.name) ? currentRole.name : 'Mickey RevOps',
      detail: `Presupuesto de campaña ${camp.name} incrementado a MXN ${camp.dailyBudget}/día. Alerta emitida a empaque.`,
      type: 'marketing'
    });
  }

  if (typeof showToast === 'function') {
    showToast(`Presupuesto escalado a MXN ${camp.dailyBudget}. Alerta TASK-INT-12 enviada a empaque para amortiguar demanda.`);
  }

  const currentScr = (typeof document !== 'undefined' && document.querySelector('.module-link.active')?.dataset?.screen) || 'crm';
  if (typeof render === 'function') render(currentScr);
  return true;
}

function pauseAdCampaign(campaignId) {
  const camp = marketingState.adCampaigns.find(c => c.id === campaignId);
  if (!camp) return false;
  
  camp.status = camp.status === 'paused' ? 'active' : 'paused';
  const rec = marketingState.growthRecommendations.find(r => r.campaignId === campaignId && r.actionType === 'pause_campaign');
  if (rec) rec.executed = true;

  if (typeof showToast === 'function') {
    showToast(`Campaña "${camp.name}" ${camp.status === 'paused' ? 'pausada por fatiga de creativo' : 'reactivada exitosamente'}.`);
  }

  const currentScr = (typeof document !== 'undefined' && document.querySelector('.module-link.active')?.dataset?.screen) || 'crm';
  if (typeof render === 'function') render(currentScr);
  return true;
}

function syncWhatsAppCatalog() {
  marketingState.adsMetrics.lastCatalogSync = `Sincronizado ahora mismo (${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} hrs - 10 SKUs en sync)`;
  
  if (typeof showToast === 'function') {
    showToast('Catálogo de WhatsApp Business sincronizado con éxito. Fotos WebP y stock enlazados.');
  }

  const currentScr = (typeof document !== 'undefined' && document.querySelector('.module-link.active')?.dataset?.screen) || 'crm';
  if (typeof render === 'function') render(currentScr);
  return true;
}

function recalculateLeadScore(leadId) {
  const lead = marketingState.leads.find(l => l.id === leadId);
  if (!lead) return false;
  
  let score = 50;
  if (lead.stage === 'subscriber') score += 30;
  else if (lead.stage === 'customer') score += 20;
  else if (lead.stage === 'abandoned') score += 15;
  else if (lead.stage === 'churn') score -= 10;
  
  if (lead.ltv > 3000) score += 15;
  else if (lead.ltv > 1500) score += 10;

  if (lead.ordersCount >= 3) score += 10;

  lead.score = Math.min(100, Math.max(0, score));

  if (typeof showToast === 'function') {
    showToast(`Score RFM recalculado para ${lead.name}: ${lead.score}/100 puntos.`);
  }

  const currentScr = (typeof document !== 'undefined' && document.querySelector('.module-link.active')?.dataset?.screen) || 'crm';
  if (typeof render === 'function') render(currentScr);
  return lead.score;
}

function toggleCouponActive(couponId) {
  const coup = marketingState.coupons.find(c => c.id === couponId);
  if (!coup) return false;
  
  coup.isActive = !coup.isActive;

  if (typeof showToast === 'function') {
    showToast(`Cupón ${coup.code} ${coup.isActive ? 'activado' : 'pausado'}.`);
  }

  const currentScr = (typeof document !== 'undefined' && document.querySelector('.module-link.active')?.dataset?.screen) || 'crm';
  if (typeof render === 'function') render(currentScr);
  return coup.isActive;
}

function sendChatbotMessage(chatId, text) {
  if (!text || !text.trim()) return false;
  const chat = marketingState.conversations.find(c => c.id === chatId);
  if (!chat) return false;

  const nowTime = (typeof getFormattedTime === 'function') ? getFormattedTime() : new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  chat.messages.push({
    sender: 'agent',
    text: text.trim(),
    time: nowTime
  });
  chat.unread = false;
  chat.status = 'human_takeover';

  const currentScr = (typeof document !== 'undefined' && document.querySelector('.module-link.active')?.dataset?.screen) || 'crm';
  if (typeof render === 'function') render(currentScr);
  return true;
}

