function handleSaveCoupon() {
  const codeEl = document.getElementById('coupon-code-input');
  const typeEl = document.getElementById('coupon-type-input');
  const valEl = document.getElementById('coupon-val-input');
  const minEl = document.getElementById('coupon-min-input');
  const univEl = document.getElementById('coupon-univ-input');
  const maxEl = document.getElementById('coupon-max-input');

  if (!codeEl || !codeEl.value.trim()) {
    if (typeof showToast === 'function') showToast('Debes ingresar un código para el cupón.', 'error');
    return;
  }

  const newCoupon = {
    id: `coup-${Date.now()}`,
    code: codeEl.value.trim().toUpperCase(),
    type: typeEl ? typeEl.value : 'percent',
    value: valEl ? parseFloat(valEl.value) || 0 : 10,
    minAmount: minEl ? parseFloat(minEl.value) || 0 : 0,
    universe: univEl ? univEl.value : 'all',
    maxUses: maxEl ? parseInt(maxEl.value) || 100 : 100,
    usedCount: 0,
    isActive: true,
    expiresAt: '2026-12-31',
    revenue: 0
  };

  marketingState.coupons.unshift(newCoupon);

  if (typeof closeActionModal === 'function') closeActionModal();
  if (typeof showToast === 'function') showToast(`Cupón ${newCoupon.code} creado exitosamente.`);
  const currentScr = (typeof document !== 'undefined' && document.querySelector('.module-link.active')?.dataset?.screen) || 'crm';
  if (typeof render === 'function') render(currentScr);
}

