function switchStoreTab(tab) {
  storeState.activeTab = tab;
  const main = document.querySelector('[data-main]');
  if (main) main.innerHTML = storeBody();
}

function switchStoreUniverse(universe) {
  if (storeState.storefronts[universe]) {
    storeState.activeUniverse = universe;
    const main = document.querySelector('[data-main]');
    if (main) main.innerHTML = storeBody();
  }
}

function setPreviewDevice(device) {
  storeState.previewDevice = device;
  const frame = document.querySelector('[data-storefront-preview-frame]');
  if (frame) {
    frame.className = `storefront-preview-frame ${device}`;
  }
  document.querySelectorAll('[data-preview-device-btn]').forEach(btn => {
    btn.classList.toggle('bg-slate-900', btn.dataset.previewDeviceBtn === device);
    btn.classList.toggle('text-white', btn.dataset.previewDeviceBtn === device);
    btn.classList.toggle('text-slate-600', btn.dataset.previewDeviceBtn !== device);
  });
}

function saveStorefrontConfig(universe) {
  const nameInput = document.querySelector('[data-store-name-input]');
  const titleInput = document.querySelector('[data-store-hero-title-input]');
  const subInput = document.querySelector('[data-store-hero-sub-input]');
  const ctaInput = document.querySelector('[data-store-hero-cta-input]');
  const colorInput = document.querySelector('[data-store-accent-color-input]');

  if (storeState.storefronts[universe]) {
    if (nameInput) storeState.storefronts[universe].name = nameInput.value.trim();
    if (titleInput) storeState.storefronts[universe].heroTitle = titleInput.value.trim();
    if (subInput) storeState.storefronts[universe].heroSubtitle = subInput.value.trim();
    if (ctaInput) storeState.storefronts[universe].heroCtaText = ctaInput.value.trim();
    if (colorInput) storeState.storefronts[universe].accentColor = colorInput.value.trim();

    showToast(`Configuración de vitrina ${storeState.storefronts[universe].name} actualizada con éxito`);
    const main = document.querySelector('[data-main]');
    if (main) main.innerHTML = storeBody();
  }
}

function toggleAnnouncementBar() {
  storeState.announcementActive = !storeState.announcementActive;
  showToast(storeState.announcementActive ? 'Marquesina superior activada' : 'Marquesina superior pausada');
  const main = document.querySelector('[data-main]');
  if (main) main.innerHTML = storeBody();
}

function toggleBannerStatus(bannerId) {
  const banner = storeState.banners.find(b => b.id === Number(bannerId));
  if (banner) {
    banner.active = !banner.active;
    showToast(`Banner "${banner.title}" ${banner.active ? 'activado' : 'pausado'}`);
    const main = document.querySelector('[data-main]');
    if (main) main.innerHTML = storeBody();
  }
}

function simulateShippingThreshold(threshold) {
  threshold = parseFloat(threshold) || 999;
  storeState.simulator.currentThreshold = threshold;
  const estimatedAverageOrder = Math.max(650, threshold * 1.15);
  const projectedOrders = Math.round(120 * (1000 / threshold));
  const shippingCostAbsorbedPerOrder = 145.00;
  const freeShippingRatio = threshold <= 899 ? 65.0 : (threshold <= 1199 ? 42.0 : 25.0);
  const grossRevenue = projectedOrders * estimatedAverageOrder;
  const totalShippingAbsorbed = (projectedOrders * (freeShippingRatio / 100)) * shippingCostAbsorbedPerOrder;
  const cogsEstimated = grossRevenue * 0.38;
  const projectedNetProfit = grossRevenue - cogsEstimated - totalShippingAbsorbed - (grossRevenue * 0.036);
  const projectedEbitdaMargin = Math.round(((projectedNetProfit / grossRevenue) * 100) * 10) / 10;

  storeState.simulator.projectedOrders = projectedOrders;
  storeState.simulator.freeShippingRatio = freeShippingRatio;
  storeState.simulator.totalShippingAbsorbed = Math.round(totalShippingAbsorbed);
  storeState.simulator.projectedEbitdaMargin = projectedEbitdaMargin;
  storeState.simulator.isHealthy = projectedEbitdaMargin >= 30.0;

  const thresholdValEl = document.querySelector('[data-simulator-threshold-val]');
  const ordersValEl = document.querySelector('[data-simulator-orders-val]');
  const ratioValEl = document.querySelector('[data-simulator-ratio-val]');
  const costValEl = document.querySelector('[data-simulator-cost-val]');
  const ebitdaValEl = document.querySelector('[data-simulator-ebitda-val]');
  const healthBadgeEl = document.querySelector('[data-simulator-health-badge]');

  if (thresholdValEl) thresholdValEl.textContent = `MXN $${threshold.toLocaleString()}`;
  if (ordersValEl) ordersValEl.textContent = `${projectedOrders} pedidos/mes`;
  if (ratioValEl) ratioValEl.textContent = `${freeShippingRatio}% de pedidos`;
  if (costValEl) costValEl.textContent = `MXN $${Math.round(totalShippingAbsorbed).toLocaleString()}`;
  if (ebitdaValEl) ebitdaValEl.textContent = `${projectedEbitdaMargin}% EBITDA`;
  if (healthBadgeEl) {
    if (storeState.simulator.isHealthy) {
      healthBadgeEl.className = 'px-2 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-800';
      healthBadgeEl.textContent = 'Margen Saludable';
    } else {
      healthBadgeEl.className = 'px-2 py-0.5 rounded text-[10px] font-bold bg-amber-100 text-amber-800';
      healthBadgeEl.textContent = 'Riesgo de Margen';
    }
  }
}

function saveShippingRule() {
  const thresholdInput = document.querySelector('[data-shipping-threshold-input]');
  const flatRateInput = document.querySelector('[data-shipping-flat-input]');
  const pickupInput = document.querySelector('[data-shipping-pickup-check]');

  if (thresholdInput) storeState.shippingRule.freeShippingThreshold = parseFloat(thresholdInput.value) || 999.00;
  if (flatRateInput) storeState.shippingRule.flatRate = parseFloat(flatRateInput.value) || 149.00;
  if (pickupInput) storeState.shippingRule.localPickupEnabled = pickupInput.checked;

  showToast('Reglas comerciales y fletes actualizados');
  const main = document.querySelector('[data-main]');
  if (main) main.innerHTML = storeBody();
}

