// Acciones Interactivas y de Dominio
function calculateOrderNetMargin(orderId) {
  const ord = financeState.orderMargins.find(o => o.id === orderId || o.orderNumber === orderId);
  if (!ord) return null;
  const netProfit = ord.grossRevenue - ord.cogs - ord.gatewayFee - ord.packagingCost - ord.shippingCost;
  const netMarginPercent = ord.grossRevenue > 0 ? ((netProfit / ord.grossRevenue) * 100) : 0;
  return {
    ...ord,
    netProfit: parseFloat(netProfit.toFixed(2)),
    netMarginPercent: parseFloat(netMarginPercent.toFixed(2))
  };
}

function reconcileGatewayPayout(payoutId) {
  const payout = financeState.payouts.find(p => p.id === payoutId);
  if (!payout) return false;
  payout.status = 'reconciled';
  payout.reconciledAt = `Hoy, ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} hrs`;
  payout.bankReference = `SPEI-BBVA-${Math.floor(10000000 + Math.random() * 90000000)}`;

  if (typeof showToast === 'function') {
    showToast(`Lote bancario ${payout.id} conciliado exitosamente. Depósito de MXN ${payout.netDeposited.toLocaleString()} verificado en cuenta.`);
  }

  const currentScr = (typeof document !== 'undefined' && document.querySelector('.module-link.active')?.dataset?.screen) || 'finance';
  if (typeof render === 'function') render(currentScr);
  return true;
}

function retryDunningCharge(invoiceId) {
  const inv = financeState.dunningQueue.find(i => i.id === invoiceId);
  if (!inv) return false;

  inv.attemptsCount += 1;
  inv.status = 'paid';
  inv.failureReason = null;
  financeState.subscriptionsMetrics.dunningRecoveredRevenue += inv.amountMxn;

  if (typeof showToast === 'function') {
    showToast(`Cobro de membresía ${inv.id} (${inv.amountMxn} MXN) recuperado exitosamente en reintento.`);
  }

  const currentScr = (typeof document !== 'undefined' && document.querySelector('.module-link.active')?.dataset?.screen) || 'finance';
  if (typeof render === 'function') render(currentScr);
  return true;
}

function sendDunningWhatsAppLink(invoiceId) {
  const inv = financeState.dunningQueue.find(i => i.id === invoiceId);
  if (!inv) return false;

  inv.whatsappSent = true;
  if (typeof showToast === 'function') {
    showToast(`Enlace seguro de actualización de tarjeta enviado por WhatsApp a ${inv.customerName}.`);
  }

  const currentScr = (typeof document !== 'undefined' && document.querySelector('.module-link.active')?.dataset?.screen) || 'finance';
  if (typeof render === 'function') render(currentScr);
  return true;
}

function scheduleVendorPayout(billId) {
  const bill = financeState.vendorBills.find(b => b.id === billId);
  if (!bill) return false;

  bill.status = 'paid';
  bill.speiTrackingKey = `SPEI-BBVA-${Math.floor(10000000 + Math.random() * 90000000)}`;

  // TASK-INT-19: Sincronización Automática con Cámara de Compensación de Hub 7
  let syncedSettlement = null;
  if (typeof alliesState !== 'undefined' && Array.isArray(alliesState.clearingSettlements)) {
    syncedSettlement = alliesState.clearingSettlements.find(s =>
      s.code === bill.settlementCode ||
      s.code === bill.invoiceNumber ||
      (bill.settlementId && s.id === bill.settlementId)
    );
    if (syncedSettlement) {
      syncedSettlement.status = 'executed';
      syncedSettlement.reference = bill.speiTrackingKey;
      syncedSettlement.settledAt = new Date().toLocaleString([], { dateStyle: 'short', timeStyle: 'short' });
    }
  }

  if (typeof showToast === 'function') {
    if (syncedSettlement) {
      showToast(`Liquidación ${syncedSettlement.code} (${bill.vendorName}) dispersada vía SPEI (${bill.speiTrackingKey}). Sincronizado en Hub 7.`);
    } else {
      showToast(`Factura ${bill.invoiceNumber} marcada como pagada con clave SPEI ${bill.speiTrackingKey}.`);
    }
  }

  const currentScr = (typeof document !== 'undefined' && document.querySelector('.module-link.active')?.dataset?.screen) || 'finance';
  if (typeof render === 'function') render(currentScr);
  return true;
}

