function handleSaveVendorExpense() {
  const vendorEl = document.getElementById('expense-vendor-input');
  const catEl = document.getElementById('expense-category-input');
  const invEl = document.getElementById('expense-invoice-input');
  const amtEl = document.getElementById('expense-amount-input');
  const dateEl = document.getElementById('expense-date-input');

  if (!vendorEl || !vendorEl.value.trim() || !amtEl || !amtEl.value) {
    if (typeof showToast === 'function') showToast('Debes ingresar el proveedor y el monto del egreso.', 'error');
    return;
  }

  const newBill = {
    id: `bill-${Date.now()}`,
    vendorName: vendorEl.value.trim(),
    category: catEl ? catEl.value : 'textile_supplier',
    categoryLabel: catEl ? catEl.options[catEl.selectedIndex].text : 'Proveedor',
    invoiceNumber: invEl ? invEl.value.trim().toUpperCase() : `REM-${Date.now()}`,
    amountMxn: parseFloat(amtEl.value) || 0,
    dueDate: dateEl ? dateEl.value : '2026-09-30',
    status: 'pending',
    paymentMethod: 'spei_transfer',
    speiTrackingKey: null
  };

  financeState.vendorBills.unshift(newBill);

  if (typeof closeActionModal === 'function') closeActionModal();
  if (typeof showToast === 'function') showToast(`Egreso para ${newBill.vendorName} por MXN ${newBill.amountMxn.toLocaleString()} registrado.`);
  const currentScr = (typeof document !== 'undefined' && document.querySelector('.module-link.active')?.dataset?.screen) || 'finance';
  if (typeof render === 'function') render(currentScr);
}

// [TASK-INT-23] Sincronización Automática de Compras Planificadas hacia Finanzas (Hub 4 -> Hub 5)
window.syncPoWithFinanceState = function(poData) {
  if (typeof financeState === 'undefined') return;

  const poCode = (poData.poNumber || 'PO-2026-0000').replace('PO-', 'OC-');
  const amount = poData.total || poData.subtotal || 0;

  // 1. Asiento de Presupuesto Comprometido en Cuentas por Pagar Proyectadas (vendorBills)
  const newBill = {
    id: 'bill-po-' + String(Date.now()).slice(-4),
    vendorName: poData.supplier || 'Proveedor B2B',
    category: 'cogs_inventory',
    categoryLabel: 'Reabastecimiento Planificado (PO Emitida)',
    invoiceFolio: poCode + ' (Compromiso Presupuestal)',
    amountMxn: amount,
    dueDate: '2026-10-15',
    status: 'pending',
    paymentMethod: 'spei_transfer',
    speiTrackingKey: null,
    poReference: poCode,
    isCommittedBudget: true,
    issuedBy: 'Elena Compras'
  };

  if (!financeState.vendorBills) financeState.vendorBills = [];
  financeState.vendorBills.unshift(newBill);

  // 2. Pre-registro en Cotejo de 3 Vías Inbound (threeWayMatches - TASK-INT-07)
  if (!financeState.threeWayMatches) financeState.threeWayMatches = [];
  const existingMatch = financeState.threeWayMatches.find(m => m.poCode === poCode);
  if (!existingMatch) {
    financeState.threeWayMatches.unshift({
      id: 'twm-' + String(Date.now()).slice(-4),
      poCode: poCode,
      supplierId: poData.vendorCode || 'VND-PUR',
      supplierName: poData.supplier || 'Proveedor B2B',
      poQty: poData.totalPieces || 0,
      poUnitPrice: poData.items && poData.items[0] ? poData.items[0].costUnit : 0,
      poTotalAmount: poData.subtotal || amount,
      warehouseReceivedQty: 0,
      warehouseGoodQty: 0,
      warehouseDamagedQty: 0,
      invoiceNumber: 'Pendiente Arribo Rampa',
      invoiceQty: 0,
      invoiceGrossAmount: amount,
      matchStatus: 'pending_receipt',
      speiPayoutBlocked: true,
      discrepancyReason: 'Orden emitida en Compras (Hub 4). Presupuesto comprometido preventivamente a la espera del cotejo de rampa.',
      debitNoteNumber: null,
      debitNoteAmount: 0.00,
      payableNetAmount: amount,
      inspectedBy: 'Elena Compras (Emisión Formal)',
      updatedAt: 'Hoy, ' + new Date().toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' }) + ' hrs'
    });
  }

  if (typeof showToast === 'function') {
    showToast(`Presupuesto de $${amount.toLocaleString('es-MX', {minimumFractionDigits: 2})} MXN comprometido en Hub 5 Finanzas bajo folio ${poData.poNumber}.`, 'info');
  }
};

