// Funciones de Negocio: Hub 5 & Vendor Extranet
function exportTaxAccountantPackCsv() {
  const rows = [
    ['Folio Fiscal CFDI', 'Fecha', 'Orden', 'Pasarela', 'Cliente', 'PVP Bruto MXN', 'Base Gravable MXN', 'IVA Trasladado 16% MXN', 'Retencion ISR 1% MXN', 'Retencion IVA 8% MXN', 'Deposito Neto MXN', 'Estatus']
  ];

  financeState.taxLedger.forEach(tx => {
    rows.push([
      `"${tx.cfdiUuid}"`,
      `"${tx.date}"`,
      `"${tx.orderNumber}"`,
      `"${tx.gateway}"`,
      `"${tx.customer.replace(/"/g, '""')}"`,
      tx.pvpGross.toFixed(2),
      tx.taxableBase.toFixed(2),
      tx.ivaTransferred.toFixed(2),
      tx.retentionIsr1.toFixed(2),
      tx.retentionIva8.toFixed(2),
      tx.netSettled.toFixed(2),
      `"${tx.status}"`
    ]);
  });

  const csvContent = '\uFEFF' + rows.map(r => r.join(',')).join('\r\n');
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.setAttribute('href', url);
  link.setAttribute('download', `Paquete_Fiscal_SAT_${financeState.taxPeriod}_MarteStore.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
  showToast('Paquete fiscal SAT para contador descargado exitosamente');
}

function issueDebitNote(matchId) {
  const match = financeState.threeWayMatches.find(m => m.id === matchId);
  if (!match) return;
  match.matchStatus = 'debit_note_issued';
  match.debitNoteNumber = 'ND-2026-004';
  match.speiPayoutBlocked = false;
  match.updatedAt = `Hoy, ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} hrs`;

  const vOrder = vendorPortalState.orders.find(o => o.poCode === match.poCode);
  if (vOrder) {
    vOrder.threeWayStatus = 'debit_note_issued';
  }

  showToast(`Nota de Débito ND-2026-004 emitida por MXN $${match.debitNoteAmount.toLocaleString()}. Retención SPEI liberada.`);
  render('finance');
}

function releaseSpeiPayment(matchId) {
  const match = financeState.threeWayMatches.find(m => m.id === matchId);
  if (!match) return;
  if (match.speiPayoutBlocked) {
    showToast('Dispersión bloqueada preventivamente: Resuelva la discrepancia o emita la nota de débito.');
    return;
  }
  match.matchStatus = 'approved_for_payment';
  const speiRef = `SPEI-BBVA-${Math.floor(1000000 + Math.random() * 9000000)}`;

  const bill = financeState.vendorBills.find(b => b.vendorName.includes('Torzo') || b.amountMxn === match.poTotalAmount);
  if (bill) {
    bill.status = 'paid';
    bill.speiTrackingKey = speiRef;
    bill.amountMxn = match.payableNetAmount;
  }

  const vOrder = vendorPortalState.orders.find(o => o.poCode === match.poCode);
  if (vOrder) {
    vOrder.productionStatus = 'paid';
    vOrder.productionStatusLabel = 'Liquidado con Transferencia SPEI';
    vOrder.speiReference = speiRef;
    vOrder.paidAt = 'Hoy';
  }

  showToast(`Dispersión SPEI exitosa por MXN $${match.payableNetAmount.toLocaleString()}. Clave: ${speiRef}`);
  render('finance');
}

function confirmVendorOrder(poCode) {
  const order = vendorPortalState.orders.find(o => o.poCode === poCode);
  if (!order) return;
  order.fabricStatus = 'Corte de Tela Modal 100% Confirmado. Ensamble en curso.';
  showToast(`Orden ${poCode}: Corte de tela y confección confirmados por el taller.`);
  render('vendor');
}

