function submitVendorDispatch(poCode) {
  const order = vendorPortalState.orders.find(o => o.poCode === poCode);
  if (!order) return;
  const carrierEl = document.getElementById('vendorCarrierSelect');
  const trackingEl = document.getElementById('vendorTrackingInput');
  const remissionEl = document.getElementById('vendorRemissionInput');

  order.carrierName = (carrierEl && carrierEl.value) ? carrierEl.value : 'Fletera Potosinos Express';
  order.trackingNumber = (trackingEl && trackingEl.value) ? trackingEl.value : 'POT-8831920';
  order.remissionNumber = (remissionEl && remissionEl.value) ? remissionEl.value : 'REM-4491';
  order.productionStatus = 'delivered';
  order.productionStatusLabel = 'En Tránsito a Rampa Central';
  order.dispatchedAt = 'Hoy';

  // Disparar evento de dominio inter-hub (TASK-INT-20: Extranet Proveedores -> Hub 1 / Hub 4)
  if (typeof dispatchOperationalEvent === 'function') {
    dispatchOperationalEvent('vendor.shipment_dispatched', {
      order: order,
      poCode: order.poCode,
      supplierName: vendorPortalState.supplierName,
      carrierName: order.carrierName,
      trackingNumber: order.trackingNumber,
      remissionNumber: order.remissionNumber,
      totalPieces: order.totalPieces,
      productName: order.productName,
      sku: order.sku,
      sizes: order.sizes,
      unitCostMxn: order.unitCostMxn,
      totalAmountMxn: order.totalAmountMxn
    });
  }

  closeActionModal();
  showToast(`Despacho de orden ${poCode} registrado con guía ${order.trackingNumber}. Notificación enviada a Rampa Central.`);
  render('vendor');
}

