function accessVendorPortalByToken(token) {
  if (token === 'vnd_token_torzo_2026' || token) {
    vendorPortalState.token = token;
    vendorPortalState.isTokenAuthenticated = true;
    render('vendor');
    showToast(`Acceso concedido a Extranet B2B: ${vendorPortalState.supplierName}`);
  }
}

function exitVendorPortal() {
  render('finance');
  showToast('Has regresado al panel administrativo de Finanzas');
}

// TASK-INT-11: Inyeccion Automatica de OCs a Extranet B2B por Deficit BOM
function injectBomProcurementOrders(generatedOrders, options = {}) {
  if (!Array.isArray(generatedOrders) || generatedOrders.length === 0) {
    return { success: false, message: 'No hay ordenes generadas' };
  }

  const batchRef = options.batchReference || `SUB-BATCH-${new Date().toISOString().slice(0, 10).replace(/-/g, '')}`;
  const bundleSku = options.bundleSku || 'SUB-BOX-MARTE-LVL2';
  const targetBoxes = options.targetBoxes || 20;

  const createdOrders = [];

  generatedOrders.forEach(orderData => {
    const poCode = orderData.poCode || `OC-2026-BOM-${String(Math.floor(100 + Math.random() * 900))}`;
    const newOrder = {
      poCode: poCode,
      issueDate: orderData.issueDate || new Date().toISOString().slice(0, 10),
      expectedDockDate: orderData.expectedDockDate || new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10),
      targetDockDeadline: orderData.targetDockDeadline || orderData.expectedDockDate || new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10),
      bomProcurementCode: orderData.bomProcurementCode || `BOM-PROC-${new Date().toISOString().slice(0, 7).replace('-', '')}-001`,
      bomBatchReference: batchRef,
      supplierId: orderData.supplierId || 'VND-TORZO',
      supplierName: orderData.supplierName || (orderData.supplierId === 'VND-TERRA' ? 'Terra Labs Cosmetics' : 'Torzo Labs & Textile Co.'),
      sku: orderData.sku || bundleSku,
      productName: orderData.productName || `Insumos BOM Lote Suscripcion ${bundleSku}`,
      sizes: orderData.sizes || {},
      totalPieces: orderData.totalPieces || 0,
      unitCostMxn: orderData.unitCostMxn || 135.00,
      totalAmountMxn: orderData.totalAmountMxn || (orderData.totalPieces * (orderData.unitCostMxn || 135.00)),
      productionStatus: 'in_production',
      productionStatusLabel: 'Lote BOM En Taller de Confeccion',
      fabricStatus: 'Material Asignado y Ensamble Programado',
      carrierName: null,
      trackingNumber: null,
      remissionNumber: null,
      dispatchedAt: null,
      notes: orderData.notes || `Orden de compra generada automaticamente por deficit BOM para lote de ${targetBoxes} cajas (${bundleSku}).`
    };

    if (typeof vendorPortalState !== 'undefined' && vendorPortalState && vendorPortalState.orders) {
      vendorPortalState.orders.unshift(newOrder);
    }
    createdOrders.push(newOrder);

    // Inyectar tarea en Action Center de Hub 1
    if (typeof operationalState !== 'undefined' && operationalState && operationalState.tasks) {
      const task = {
        id: `task-bom-po-${poCode.toLowerCase().replace(/[^a-z0-9]/g, '-')}`,
        category: 'recepcion',
        badgeClass: 'urgent',
        badgeText: 'Deficit BOM',
        sla: {
          triggeredAt: typeof getFormattedTime === 'function' ? getFormattedTime() : '10:00 hrs',
          dueTime: '18:00 hrs',
          status: 'warning',
          label: 'Seguimiento Taller'
        },
        title: `Seguimiento Entrega Maquila BOM: ${poCode} (${newOrder.supplierName})`,
        desc: `Orden de reposicion para ${newOrder.totalPieces} insumos de ensamble (${batchRef}). Fecha fatal en rampa: ${newOrder.expectedDockDate}.`,
        meta: `Proveedor: ${newOrder.supplierName} • Piezas: ${newOrder.totalPieces} • Ref: ${batchRef}`,
        detail: `Proveedor: ${newOrder.supplierName} • Piezas: ${newOrder.totalPieces} • Ref: ${batchRef}`,
        actionKey: 'open-ramp-dock',
        actionLabel: 'Ver en Extranet',
        status: 'pending',
        data: {
          poCode: poCode,
          supplierId: newOrder.supplierId,
          supplierName: newOrder.supplierName,
          totalPieces: newOrder.totalPieces,
          batchReference: batchRef,
          checks: [
            { id: `chk-bom-conf-${Date.now()}`, label: 'Confirmacion de taller recibida', checked: false },
            { id: `chk-bom-track-${Date.now()}`, label: 'Fecha de entrega en rampa validada', checked: false }
          ]
        }
      };
      operationalState.tasks.unshift(task);
    }
  });

  // Registrar en bitacora de turno (shiftLog)
  if (typeof operationalState !== 'undefined' && operationalState && operationalState.shiftLog) {
    const poCodesStr = createdOrders.map(o => o.poCode).join(', ');
    operationalState.shiftLog.unshift({
      id: `shift-log-bom-${Date.now()}`,
      time: typeof getFormattedTime === 'function' ? getFormattedTime() : '12:00 PM',
      action: `Disparo Automatico OCs BOM (${poCodesStr})`,
      user: 'Supervisor Ensamble BOM',
      detail: `Generadas ${createdOrders.length} OCs a Extranet B2B para solventar deficit de ensamble (${targetBoxes} cajas ${bundleSku}, lote ${batchRef}).`,
      type: 'compras'
    });
  }

  if (typeof showToast === 'function') {
    showToast(`Se generaron ${createdOrders.length} ordenes de compra hacia la Extranet B2B.`);
  }

  return { success: true, createdOrders: createdOrders };
}

// Notificación Reactiva al Extranet del Proveedor al Emitir Orden de Compra (TASK-HUB-VND / TASK-PUR-04)
function notifyVendorExtranetNewPo(poData) {
  if (!poData) return;
  const v = (typeof window !== 'undefined' && window.vendorPortalState) ? window.vendorPortalState : vendorPortalState;
  if (!v) return;

  // 1. Notificación en el Feed del Dashboard del Proveedor
  v.notifications = v.notifications || [];
  const timeStr = typeof getFormattedTime === 'function' ? getFormattedTime() : new Date().toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' });
  const deductionNote = (poData.deductionAmount > 0)
    ? ` (Compensación aplicada: -$${poData.deductionAmount.toFixed(2)} MXN bajo acuerdo ${poData.creditNoteRef})`
    : '';

  v.notifications.unshift({
    id: `notif-po-${Date.now()}`,
    time: `Hoy, ${timeStr} hrs`,
    title: `Nueva Orden de Compra Emitida: ${poData.poNumber}`,
    detail: `${poData.totalPieces} prendas • Total a transferir: $${(poData.total || 0).toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} MXN${deductionNote}. Despachada formalmente por RevOps Compras.`,
    poNumber: poData.poNumber,
    supplier: poData.supplier
  });

  // 2. Registro formal de la orden en la bandeja de OCs del Extranet
  v.orders = v.orders || [];
  const primaryItem = (poData.items && poData.items[0]) ? poData.items[0] : null;
  const existingOrder = v.orders.find(o => o.poCode === poData.poNumber);

  if (!existingOrder) {
    const itemSizes = (primaryItem && primaryItem.sizes)
      ? primaryItem.sizes
      : { CH: Math.round(poData.totalPieces * 0.2), M: Math.round(poData.totalPieces * 0.4), G: Math.round(poData.totalPieces * 0.3), XL: Math.round(poData.totalPieces * 0.1) };

    const newOrder = {
      poCode: poData.poNumber,
      issueDate: poData.date || new Date().toISOString().split('T')[0],
      expectedDockDate: poData.deliveryCommitmentDate || '5 días hábiles posteriores a emisión',
      sku: primaryItem ? primaryItem.sku : 'LOTE-VARIOS',
      productName: (poData.items && poData.items.length === 1) ? primaryItem.productName : `Lote Oficial ${poData.poNumber} (${poData.items.length} partidas)`,
      sizes: itemSizes,
      totalPieces: poData.totalPieces,
      unitCostMxn: primaryItem ? primaryItem.costUnit : (poData.subtotal / (poData.totalPieces || 1)),
      totalAmountMxn: poData.total,
      grossAmountMxn: poData.grossSubtotal || poData.subtotal,
      deductionAmountMxn: poData.deductionAmount || 0,
      creditNoteRef: poData.creditNoteRef || null,
      productionStatus: 'in_production',
      productionStatusLabel: 'Nueva OC Emitida por RevOps',
      fabricStatus: 'Pendiente Confirmar Confección por Proveedor',
      carrierName: null,
      trackingNumber: null,
      remissionNumber: null,
      dispatchedAt: null,
      notes: (poData.deductionAmount > 0 ? `Acuerdo ${poData.creditNoteRef} aplicado (-$${poData.deductionAmount.toFixed(2)} MXN). ` : '') + (poData.notes || 'Emitida oficialmente desde Compras RevOps.')
    };
    v.orders.unshift(newOrder);
  }

  // 3. Bitácora de Turno en Hub 1 (Action Center)
  if (typeof operationalState !== 'undefined' && operationalState && operationalState.shiftLog) {
    operationalState.shiftLog.unshift({
      id: `shift-log-po-${Date.now()}`,
      time: timeStr,
      action: `Emisión de PO ${poData.poNumber} a Extranet`,
      user: poData.buyerAgent || 'Elena Compras',
      detail: `Orden ${poData.poNumber} notificada al Extranet B2B del proveedor (${poData.totalPieces} pzas, $${(poData.total || 0).toLocaleString('es-MX', { minimumFractionDigits: 2 })} MXN).`,
      type: 'compras'
    });
  }

  // 4. Si la pantalla activa es Extranet Proveedores ('vendor'), refrescar la vista
  if (typeof currentScreen !== 'undefined' && currentScreen === 'vendor' && typeof render === 'function') {
    render('vendor');
  }
}

