// 6.9 PANTALLA DE ACCESO RESTRINGIDO POR ROL OPERATIVO (RBAC GUARD)
function renderAccessDenied(screenKey, screen) {
  const mainEl = document.querySelector('[data-main]');
  if (!mainEl) return;

  const hubTitleEl = document.querySelector('[data-hub-title]');
  const hubKickerEl = document.querySelector('[data-hub-kicker]');
  const hubStatusEl = document.querySelector('[data-hub-status]');

  if (hubTitleEl) hubTitleEl.textContent = 'Acceso Restringido';
  if (hubKickerEl) hubKickerEl.textContent = 'Segregación de Funciones';
  if (hubStatusEl) {
    hubStatusEl.className = 'hub-status executive';
    hubStatusEl.textContent = 'Módulo No Autorizado';
  }

  const primary = currentRole.primaryHub || (currentRole.allowedHubs && currentRole.allowedHubs[0]) || 'dashboard';
  const primaryScreen = screens[primary] || { title: primary };
  const primaryTitle = primaryScreen.title || primary;

  const allowedPills = (currentRole.allowedHubs || []).map(h => {
    const s = screens[h] || { title: h };
    return `<button class="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-800 rounded-lg text-xs font-semibold transition cursor-pointer" onclick="render('${h}')">${s.title || h}</button>`;
  }).join(' ');

  mainEl.innerHTML = `
    <div class="max-w-2xl mx-auto py-16 px-4 text-center">
      <div class="w-16 h-16 bg-rose-50 text-rose-600 rounded-2xl mx-auto mb-6 flex items-center justify-center border border-rose-100 shadow-sm">
        <svg class="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
      </div>
      <span class="inline-block px-3 py-1 rounded-full text-xs font-bold bg-rose-100 text-rose-800 uppercase tracking-wider mb-3">Acceso Restringido por Perfil Operativo</span>
      <h2 class="text-2xl font-black text-slate-900 mb-2">Módulo no autorizado para tu rol</h2>
      <p class="text-sm text-slate-600 mb-6 leading-relaxed">
        El perfil actual <strong class="text-slate-900">${currentRole.roleTitle}</strong> (${currentRole.name}) no cuenta con autorización normativa para acceder a la pantalla <strong>${screen ? (screen.title || screenKey) : screenKey}</strong>.
      </p>
      
      <div class="bg-amber-50 border border-amber-200 rounded-xl p-4 text-left text-xs text-amber-900 mb-8 leading-relaxed">
        <div class="font-bold mb-1 flex items-center gap-1.5">
          <svg class="w-4 h-4 text-amber-700 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
          <span>Política de Privacidad y Segregación de Puestos:</span>
        </div>
        <p class="text-amber-800">
          Para garantizar la confidencialidad de costos de adquisición, facturación comercial y balances financieros (conforme a <em>ROLES_AND_WORKFLOWS_SPEC.md</em>), este módulo está reservado para los roles designados.
        </p>
      </div>

      <div class="flex flex-col sm:flex-row items-center justify-center gap-3 mb-8">
        <button class="w-full sm:w-auto px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs font-bold transition shadow-sm cursor-pointer" onclick="render('${primary}')">
          Ir a mi Módulo Principal (${primaryTitle})
        </button>
        <button class="w-full sm:w-auto px-5 py-2.5 bg-white border border-slate-300 hover:bg-slate-50 text-slate-700 rounded-xl text-xs font-bold transition shadow-sm cursor-pointer" onclick="if(document.querySelector('[data-roles-modal]')){document.querySelector('[data-roles-modal]').style.display='flex'; renderRolesList();}">
          Cambiar de Rol
        </button>
      </div>

      <div class="pt-6 border-t border-slate-200">
        <span class="text-xs font-semibold text-slate-500 block mb-3 uppercase tracking-wider">Tus módulos habilitados:</span>
        <div class="flex flex-wrap items-center justify-center gap-2">
          ${allowedPills}
        </div>
      </div>
    </div>
  `;
}

// 7. FUNCIÓN PRINCIPAL DE RENDERIZADO
function render(name = 'inventory') {
  const resolvedName = screenAliases[name] || name;
  const screen = screens[resolvedName] || screens.inventory;

  // Actualizar estado activo en Sidebar
  document.querySelectorAll('.module-link').forEach(link => {
    link.classList.toggle('active', link.dataset.screen === resolvedName);
  });

  // VERIFICACIÓN DE ACCESO POR ROL (RBAC SCREEN GUARD)
  const allowed = Array.isArray(currentRole.allowedHubs) ? currentRole.allowedHubs : [];
  const isAllowed = allowed.includes(resolvedName) || currentRole.id === 'admin' || currentRole.id === 'all_roles' || resolvedName === 'settings';

  if (!isAllowed) {
    renderAccessDenied(resolvedName, screen);
    closeMobile();
    return;
  }

  if (resolvedName !== 'settings') {
    window.lastNonSettingsScreen = resolvedName;
  }

  // Actualizar Titulo, Kicker y Badge de Estado en Topbar / Navbar
  const hubTitleEl = document.querySelector('[data-hub-title]');
  const hubKickerEl = document.querySelector('[data-hub-kicker]');
  const hubStatusEl = document.querySelector('[data-hub-status]');

  if (hubTitleEl) hubTitleEl.textContent = screen.title;
  if (hubKickerEl) hubKickerEl.textContent = screen.hubKicker || 'Hub';

  // Actualizar botón canónico de Ajustes de Módulo en Navbar
  const moduleSettingsBtn = document.querySelector('[data-action="toggle-module-settings"]');
  if (moduleSettingsBtn) {
    moduleSettingsBtn.title = `Ajustes del Módulo: ${screen.title || 'Inventario'}`;
    moduleSettingsBtn.setAttribute('aria-label', `Ajustes del Módulo: ${screen.title || 'Inventario'}`);
  }

  if (hubStatusEl) {
    hubStatusEl.classList.remove('executive', 'operative');
    hubStatusEl.classList.remove('sales');
    if (resolvedName === 'dashboard') {
      const effTab = getEffectiveDashboardTab();
      if (effTab === 'sales') {
        hubStatusEl.textContent = 'Atención & Ventas';
        hubStatusEl.classList.add('sales');
      } else if (effTab === 'operative') {
        hubStatusEl.textContent = 'Vista Operativa';
        hubStatusEl.classList.add('operative');
      } else {
        hubStatusEl.textContent = currentRole.isExecutive ? 'Vista Ejecutiva' : 'Vista Operativa';
        hubStatusEl.classList.add('executive');
      }
    } else if (resolvedName === 'inventory') {
      hubStatusEl.textContent = '1,736 Piezas en Bodega';
      hubStatusEl.classList.add('operative');
    } else if (resolvedName === 'logistics') {
      const readyCount = logisticsState.packages.filter(p => p.status === 'packed').length;
      hubStatusEl.textContent = `${readyCount} Bultos Listos para Salida`;
      hubStatusEl.classList.add('operative');
    } else if (resolvedName === 'crm') {
      const hotCount = marketingState.leads.filter(l => l.score >= 80).length;
      hubStatusEl.textContent = `${hotCount} Hot Leads Listos`;
      hubStatusEl.classList.add('executive');
    } else if (resolvedName === 'finance') {
      hubStatusEl.textContent = 'MXN $112,400 MRR Activo';
      hubStatusEl.classList.add('executive');
    } else if (resolvedName === 'store') {
      hubStatusEl.textContent = '4 Vitrinas Activas';
      hubStatusEl.classList.add('executive');
    } else if (resolvedName === 'allies') {
      hubStatusEl.textContent = '5 Aliados Activos';
      hubStatusEl.classList.add('executive');
    } else if (resolvedName === 'vendor') {
      hubStatusEl.textContent = 'Extranet B2B Activa';
      hubStatusEl.classList.add('executive');
    } else {
      hubStatusEl.textContent = 'Activo';
    }
  }

  // Renderizar contenido en main (CERO CABECERAS REDUNDANTES, MAXIMO ESPACIO VERTICAL - REGLA 10: TABS PRIMERO, KPIS DEBAJO)
  if (resolvedName === 'inventory' && typeof window.hybridInventoryBody === 'function') {
    main.innerHTML = window.hybridInventoryBody();
    if (window.Alpine && typeof window.Alpine.initTree === 'function') {
      window.Alpine.initTree(main);
    }
  } else if (resolvedName === 'dashboard') {
    main.innerHTML = dashboardBody();
  } else if (resolvedName === 'logistics') {
    main.innerHTML = logisticsBody();
  } else if (resolvedName === 'crm') {
    main.innerHTML = marketingBody();
  } else if (resolvedName === 'finance') {
    main.innerHTML = financeBody();
  } else if (resolvedName === 'store') {
    main.innerHTML = storeBody();
  } else if (resolvedName === 'allies') {
    main.innerHTML = alliesBody();
  } else if (resolvedName === 'vendor') {
    main.innerHTML = vendorPortalBody();
  } else if (resolvedName === 'settings') {
    main.innerHTML = systemSettingsBody();
    initSystemSettingsView(main);
  } else {
    main.innerHTML = genericHubBody(screen, resolvedName);
  }

  closeMobile();
}

function closeMobile() {
  sidebar.classList.remove('mobile-open');
  overlay.classList.remove('show');
}

// 8. MANEJO DE NAVEGACIÓN EN SIDEBAR
document.querySelectorAll('.module-link').forEach(link => {
  link.addEventListener('click', () => {
    render(link.dataset.screen);
  });
});

document.querySelector('[data-action="collapse"]').addEventListener('click', () => {
  document.body.classList.toggle('collapsed');
});

document.querySelector('[data-action="toggle-menu"]').addEventListener('click', () => {
  sidebar.classList.add('mobile-open');
  overlay.classList.add('show');
});

overlay.addEventListener('click', closeMobile);

// 9. GESTION DE NOTIFICACIONES Y DEEP LINKS EN TIEMPO REAL (TASK-UX-03)
const notifPopover = document.querySelector('[data-notif-popover]');
const notifBtn = document.querySelector('[data-action="toggle-notifications"]');
const notifBadge = document.querySelector('[data-notif-badge]');
const notifList = document.querySelector('[data-notif-list]');
const notifStatusText = document.querySelector('[data-notif-status-text]');

let liveNotifications = [];

async function fetchNotifications() {
  try {
    const res = await fetch('/api/v1/governance/notifications', {
      headers: {
        'Accept': 'application/json',
        'X-Requested-With': 'XMLHttpRequest',
      }
    });
    if (!res.ok) return;
    const data = await res.json();
    if (!data.success) return;

    liveNotifications = data.data || [];
    renderNotifications(data);
  } catch (err) {
    console.warn('Error al cargar notificaciones operativas:', err);
  }
}

function renderNotifications(data) {
  const unreadCount = data.unread_count || 0;
  const items = data.data || [];

  // Actualizar badge
  if (notifBadge) {
    if (unreadCount > 0) {
      notifBadge.textContent = unreadCount > 99 ? '99+' : unreadCount;
      notifBadge.style.display = 'inline-flex';
    } else {
      notifBadge.style.display = 'none';
    }
  }

  // Actualizar subtitulo
  if (notifStatusText) {
    notifStatusText.textContent = unreadCount > 0
      ? `${unreadCount} alerta${unreadCount > 1 ? 's' : ''} pendiente${unreadCount > 1 ? 's' : ''}`
      : 'Todas las alertas al dia';
  }

  // Actualizar contadores de tabs
  const countAll = document.querySelector('[data-notif-count-all]');
  const countCrit = document.querySelector('[data-notif-count-critical]');
  const countInfo = document.querySelector('[data-notif-count-info]');

  if (countAll) countAll.textContent = data.total || items.length;
  if (countCrit) countCrit.textContent = (data.categories?.critical || []).length;
  if (countInfo) countInfo.textContent = (data.categories?.info || []).length;

  if (!notifList) return;

  if (items.length === 0) {
    notifList.innerHTML = `
      <div class="p-6 text-center text-xs text-slate-500">
        No hay notificaciones pendientes para tu rol.
      </div>
    `;
    return;
  }

  notifList.innerHTML = items.map(item => {
    const dotColor = item.badge_color || 'blue';
    const isCritical = item.type === 'critical' || item.type === 'urgent';
    const categoryAttr = isCritical ? 'critical' : 'info';
    const deepLink = item.deep_link || '#';
    const actionLabel = item.action_label || 'Atender Folio en 1 Clic';

    return `
      <div class="notif-item ${item.is_read ? 'read' : 'unread'}" data-notif-id="${item.id}" data-notif-category="${categoryAttr}">
        <div class="notif-icon-col">
          <span class="notif-alert-dot ${dotColor}"></span>
        </div>
        <div class="notif-content-col">
          <div class="notif-item-title">${item.title}</div>
          <p class="notif-item-desc">${item.message}</p>
          <div class="notif-item-footer">
            <span class="notif-time">${item.time_ago || 'Reciente'}</span>
            <a class="button button-light notif-action-btn" href="${deepLink}" data-notif-action-link="${item.id}">
              ${actionLabel}
            </a>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

async function markNotificationAsRead(id) {
  try {
    const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content');
    const res = await fetch(`/api/v1/governance/notifications/${id}/mark-read`, {
      method: 'POST',
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'X-CSRF-TOKEN': csrfToken || '',
        'X-Requested-With': 'XMLHttpRequest',
      }
    });
    if (res.ok) {
      const data = await res.json();
      if (data.success && typeof data.unread_count === 'number') {
        if (notifBadge) {
          if (data.unread_count > 0) {
            notifBadge.textContent = data.unread_count;
            notifBadge.style.display = 'inline-flex';
          } else {
            notifBadge.style.display = 'none';
          }
        }
      }
    }
  } catch (err) {
    console.warn('Error al marcar notificacion como leida:', err);
  }
}

async function markAllNotificationsAsRead() {
  try {
    const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content');
    const res = await fetch('/api/v1/governance/notifications/mark-all-read', {
      method: 'POST',
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'X-CSRF-TOKEN': csrfToken || '',
        'X-Requested-With': 'XMLHttpRequest',
      }
    });
    if (res.ok) {
      document.querySelectorAll('.notif-item').forEach(item => {
        item.classList.remove('unread');
        item.classList.add('read');
      });
      if (notifBadge) notifBadge.style.display = 'none';
      if (notifStatusText) notifStatusText.textContent = 'Todas las alertas al dia';
      showToast('Todas las notificaciones marcadas como leidas', 'success');
    }
  } catch (err) {
    console.warn('Error al marcar todas como leidas:', err);
  }
}

if (notifBtn && notifPopover) {
  notifBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    const isHidden = notifPopover.style.display === 'none';
    notifPopover.style.display = isHidden ? 'flex' : 'none';
    notifBtn.classList.toggle('active', isHidden);
    if (isHidden) {
      fetchNotifications();
    }
  });

  document.addEventListener('click', (e) => {
    if (!notifPopover.contains(e.target) && !notifBtn.contains(e.target)) {
      notifPopover.style.display = 'none';
      notifBtn.classList.remove('active');
    }
  });

  // Filtros de pestanas de notificaciones
  document.querySelectorAll('[data-notif-tab]').forEach(tab => {
    tab.addEventListener('click', () => {
      document.querySelectorAll('[data-notif-tab]').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      const cat = tab.dataset.notifTab;
      document.querySelectorAll('.notif-item').forEach(item => {
        if (cat === 'all') {
          item.style.display = 'flex';
        } else {
          item.style.display = item.dataset.notifCategory === cat ? 'flex' : 'none';
        }
      });
    });
  });

  // Boton marcar todas como leidas
  const markReadBtn = document.querySelector('[data-action="mark-all-read"]');
  if (markReadBtn) {
    markReadBtn.addEventListener('click', () => {
      markAllNotificationsAsRead();
    });
  }

  // Click en deep link dentro de notificaciones marca como leida
  if (notifList) {
    notifList.addEventListener('click', (e) => {
      const link = e.target.closest('[data-notif-action-link]');
      if (link) {
        const id = link.dataset.notifActionLink;
        if (id) {
          markNotificationAsRead(id);
        }
      }
    });
  }
}

// Carga inicial reactiva de notificaciones al iniciar la sesion
fetchNotifications();
window.reloadNotifications = fetchNotifications;

// 10. GESTION DEL CHAT INTER-AREAS VINCULADO A FOLIOS (TASK-COM-01)
const chatContainer = document.querySelector('[data-chat-container]');
const chatBtn = document.querySelector('[data-action="toggle-chat"]');
const chatHeaderBadge = document.querySelector('[data-chat-badge]');
const chatMessagesWrap = document.querySelector('[data-chat-messages]');
const chatInput = document.querySelector('[data-chat-input]');
const chatForm = document.querySelector('[data-chat-form]');
const chatPrioritySelect = document.querySelector('[data-chat-priority]');

async function fetchChatSummary() {
  try {
    const res = await fetch('/api/v1/governance/chat/summary', {
      headers: { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' }
    });
    if (!res.ok) return;
    const data = await res.json();
    if (!data.success || !data.summary) return;

    const summary = data.summary;
    const totalUnresolved = summary.total_unresolved || 0;

    if (chatHeaderBadge) {
      if (totalUnresolved > 0) {
        chatHeaderBadge.textContent = totalUnresolved > 99 ? '99+' : totalUnresolved;
        chatHeaderBadge.style.display = 'inline-flex';
      } else {
        chatHeaderBadge.style.display = 'none';
      }
    }

    ['almacen', 'ventas', 'logistica', 'general'].forEach(ch => {
      const badge = document.querySelector(`[data-channel-count="${ch}"]`);
      if (badge) {
        const count = summary[ch] || 0;
        if (count > 0) {
          badge.textContent = count;
          badge.style.display = 'inline-block';
        } else {
          badge.style.display = 'none';
        }
      }
    });
  } catch (err) {
    console.warn('Error al consultar resumen de chat:', err);
  }
}

async function fetchChannelMessages(channel) {
  if (!chatMessagesWrap) return;
  try {
    const res = await fetch(`/api/v1/governance/chat/messages?channel=${channel}`, {
      headers: { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' }
    });
    if (!res.ok) return;
    const data = await res.json();
    if (!data.success) return;

    renderChatMessagesFromApi(data.messages || []);
    fetchChatSummary();
  } catch (err) {
    console.warn('Error al cargar mensajes del canal:', err);
  }
}

function renderChatMessagesFromApi(messages) {
  if (!chatMessagesWrap) return;

  if (messages.length === 0) {
    chatMessagesWrap.innerHTML = `
      <div class="p-6 text-center text-xs text-slate-400">
        No hay mensajes registrados en este canal operativo.
      </div>
    `;
    return;
  }

  chatMessagesWrap.innerHTML = messages.map(m => {
    const initials = (m.sender || 'OP').slice(0, 2).toUpperCase();
    const isMine = m.isMine ? 'mine' : '';
    const isResolved = m.is_resolved;
    const priorityBadge = m.priority === 'urgent'
      ? '<span class="inline-block px-1.5 py-0.5 rounded text-[10px] font-bold bg-rose-100 text-rose-800 ml-1">Urgente</span>'
      : (m.priority === 'high' ? '<span class="inline-block px-1.5 py-0.5 rounded text-[10px] font-bold bg-amber-100 text-amber-800 ml-1">Alta</span>' : '');

    return `
      <div class="chat-msg-row ${isMine}" data-msg-id="${m.id}">
        <div class="chat-msg-avatar">${initials}</div>
        <div class="chat-msg-body">
          <div class="chat-msg-meta flex items-center justify-between">
            <div>
              <strong>${m.sender}</strong>
              <span class="text-[10px] text-slate-400 ml-1">(${m.role || 'Operador'})</span>
              ${priorityBadge}
            </div>
            <span class="text-[10px] text-slate-400">${m.time}</span>
          </div>
          <div class="chat-msg-bubble">
            <div>${m.text}</div>
            <div class="flex items-center justify-between mt-1 gap-2">
              ${m.tag ? `<div class="chat-tag-badge text-[11px] font-mono">${m.tag}</div>` : '<div></div>'}
              ${!isResolved
                ? `<button type="button" class="text-[10px] text-indigo-600 hover:text-indigo-800 font-semibold underline" data-resolve-msg="${m.id}">Resolver</button>`
                : `<span class="text-[10px] text-emerald-600 font-medium">Resuelto</span>`
              }
            </div>
          </div>
        </div>
      </div>
    `;
  }).join('');

  chatMessagesWrap.scrollTop = chatMessagesWrap.scrollHeight;
}

async function sendChatMessage(channel, text, priority) {
  try {
    const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content');
    const res = await fetch('/api/v1/governance/chat/messages', {
      method: 'POST',
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'X-CSRF-TOKEN': csrfToken || '',
        'X-Requested-With': 'XMLHttpRequest'
      },
      body: JSON.stringify({
        channel: channel,
        message: text,
        priority: priority || 'normal',
        sender_name: currentRole?.name || 'Operador',
        sender_role: currentRole?.id || 'operator'
      })
    });

    if (res.ok) {
      if (chatInput) chatInput.value = '';
      fetchChannelMessages(channel);
      fetchChatSummary();
      showToast('Mensaje operativo registrado con exito', 'success');
    }
  } catch (err) {
    console.warn('Error al transmitir mensaje de chat:', err);
  }
}

async function resolveChatMessage(id) {
  try {
    const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content');
    const res = await fetch(`/api/v1/governance/chat/messages/${id}/resolve`, {
      method: 'POST',
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'X-CSRF-TOKEN': csrfToken || '',
        'X-Requested-With': 'XMLHttpRequest'
      }
    });

    if (res.ok) {
      fetchChannelMessages(chatState.activeChannel);
      fetchChatSummary();
      showToast('Nota operativa resuelta correctamente', 'success');
    }
  } catch (err) {
    console.warn('Error al resolver mensaje:', err);
  }
}

if (chatBtn && chatContainer) {
  chatBtn.addEventListener('click', () => {
    chatContainer.style.display = 'flex';
    fetchChannelMessages(chatState.activeChannel);
    if (chatInput) chatInput.focus();
  });

  document.querySelectorAll('[data-action="close-chat"]').forEach(btn => {
    btn.addEventListener('click', () => {
      chatContainer.style.display = 'none';
    });
  });

  // Selector de canales
  document.querySelectorAll('[data-channel]').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('[data-channel]').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      chatState.activeChannel = btn.dataset.channel;
      fetchChannelMessages(chatState.activeChannel);
    });
  });

  // Chips de contexto rapido
  document.querySelectorAll('[data-chip]').forEach(chip => {
    chip.addEventListener('click', () => {
      if (chatInput) {
        chatInput.value += (chatInput.value ? ' ' : '') + chip.dataset.chip;
        chatInput.focus();
      }
    });
  });

  // Resolver mensaje al hacer clic en el boton Resolver
  if (chatMessagesWrap) {
    chatMessagesWrap.addEventListener('click', (e) => {
      const resolveBtn = e.target.closest('[data-resolve-msg]');
      if (resolveBtn) {
        const id = resolveBtn.dataset.resolveMsg;
        if (id) resolveChatMessage(id);
      }
    });
  }

  // Envio de mensajes
  if (chatForm) {
    chatForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const text = chatInput ? chatInput.value.trim() : '';
      if (!text) return;
      const priority = chatPrioritySelect ? chatPrioritySelect.value : 'normal';
      sendChatMessage(chatState.activeChannel, text, priority);
    });
  }
}

// Carga reactiva de contadores de chat
fetchChatSummary();
window.reloadChatSummary = fetchChatSummary;

// 11. GESTIÓN DE ROLES (RBAC MODAL)
const rolesModal = document.querySelector('[data-roles-modal]');
const rolesList = document.querySelector('[data-roles-list]');
const userRolesBtn = document.querySelector('[data-action="open-user-roles"]');

function updateRoleUI() {
  const avatarBadge = document.querySelector('[data-user-avatar-badge]');
  const displayName = document.querySelector('[data-user-display-name]');
  const displayRole = document.querySelector('[data-user-display-role]');
  const hubStatusEl = document.querySelector('[data-hub-status]');

  if (avatarBadge) avatarBadge.textContent = currentRole.avatar;
  if (displayName) displayName.textContent = currentRole.name;
  if (displayRole) displayRole.textContent = currentRole.roleTitle;

  // Filtrar visibilidad de accesos en el Sidebar según allowedHubs del rol activo
  const allowed = Array.isArray(currentRole.allowedHubs) ? currentRole.allowedHubs : [];
  document.querySelectorAll('.module-link').forEach(link => {
    const screenKey = link.dataset.screen;
    if (allowed.includes(screenKey) || currentRole.id === 'admin' || currentRole.id === 'all_roles') {
      link.style.display = 'flex';
    } else {
      link.style.display = 'none';
    }
  });

  // Sincronizar rol globalmente y despachar evento para módulos reactivos (ej. Alpine/Inventario)
  window.currentRole = currentRole;
  if (typeof window !== 'undefined' && typeof window.dispatchEvent === 'function') {
    window.dispatchEvent(new CustomEvent('role-changed', { detail: { role: currentRole } }));
  }

  const activeLink = document.querySelector('.module-link.active');
  const activeScreen = activeLink ? activeLink.dataset.screen : 'inventory';
  if (hubStatusEl && activeScreen === 'dashboard') {
    const effTab = getEffectiveDashboardTab();
    hubStatusEl.classList.remove('executive', 'operative');
    hubStatusEl.classList.remove('sales');
    if (effTab === 'sales') {
      hubStatusEl.textContent = 'Atención & Ventas';
      hubStatusEl.classList.add('sales');
    } else if (effTab === 'operative') {
      hubStatusEl.textContent = 'Vista Operativa';
      hubStatusEl.classList.add('operative');
    } else {
      hubStatusEl.textContent = currentRole.isExecutive ? 'Vista Ejecutiva' : 'Vista Operativa';
      hubStatusEl.classList.add('executive');
    }
  }
}

function renderRolesList() {
  if (!rolesList) return;
  rolesList.innerHTML = Object.values(ROLES).map(r => `
    <div class="p-3 border rounded-lg cursor-pointer transition-all flex items-center justify-between ${r.id === currentRole.id ? 'border-indigo-600 bg-indigo-50/70' : 'border-slate-200 hover:border-slate-400 bg-white'}" data-select-role="${r.id}">
      <div class="flex items-center gap-3">
        <div class="w-8 h-8 rounded-full bg-slate-900 text-white font-bold text-xs grid place-items-center">${r.avatar}</div>
        <div>
          <div class="text-xs font-bold text-slate-900 flex items-center gap-2">
            ${r.name}
            ${r.isExecutive ? '<span class="px-1.5 py-0.5 rounded bg-emerald-100 text-emerald-800 text-[9px] font-bold">Ejecutivo</span>' : '<span class="px-1.5 py-0.5 rounded bg-amber-100 text-amber-800 text-[9px] font-bold">Operativo</span>'}
            ${r.isSystem ? '<span class="px-1.5 py-0.5 rounded bg-slate-100 text-slate-600 text-[9px] font-bold">Sistema</span>' : '<span class="px-1.5 py-0.5 rounded bg-indigo-100 text-indigo-700 text-[9px] font-bold">Personalizado</span>'}
          </div>
          <div class="text-[11px] text-slate-500">${r.description}</div>
        </div>
      </div>
      ${r.id === currentRole.id ? '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="#4f46e5" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>' : ''}
    </div>
  `).join('');

  rolesList.querySelectorAll('[data-select-role]').forEach(el => {
    el.addEventListener('click', () => {
      const roleId = el.dataset.selectRole;
      currentRole = ROLES[roleId];
      if (roleId === 'sales') {
        activeDashboardTab = 'sales';
      } else if (roleId === 'warehouse' || roleId === 'packer' || !currentRole.isExecutive) {
        activeDashboardTab = 'operative';
      } else {
        activeDashboardTab = 'executive';
      }
      updateRoleUI();
      if (rolesModal) rolesModal.style.display = 'none';
      showToast(`Rol cambiado a: ${currentRole.roleTitle}`);

      // Sincronizar rol activo en sesion del backend (TASK-RBAC-02, TASK-RBAC-03)
      fetch('/admin/roles/switch', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || ''
        },
        body: JSON.stringify({ role: roleId })
      }).catch(function() {});
      
      // Re-renderizar la pantalla actual o redirigir al módulo principal del nuevo rol
      if (roleId === 'vendor') {
        vendorPortalState.isTokenAuthenticated = true;
        render('vendor');
      } else {
        const activeLink = document.querySelector('.module-link.active');
        const activeScreen = activeLink ? activeLink.dataset.screen : 'inventory';
        const allowed = Array.isArray(currentRole.allowedHubs) ? currentRole.allowedHubs : [];
        if (!allowed.includes(activeScreen) && currentRole.id !== 'admin' && currentRole.id !== 'all_roles') {
          const targetScreen = currentRole.primaryHub || allowed[0] || 'dashboard';
          render(targetScreen);
        } else {
          render(activeScreen);
        }
      }
    });
  });
}

if (userRolesBtn && rolesModal) {
  userRolesBtn.addEventListener('click', () => {
    rolesModal.style.display = 'flex';
    renderRolesList();
  });

  document.querySelectorAll('[data-action="close-roles-modal"]').forEach(btn => {
    btn.addEventListener('click', () => {
      rolesModal.style.display = 'none';
    });
  });

  document.querySelectorAll('[data-action="open-rbac-console"]').forEach(btn => {
    btn.addEventListener('click', () => {
      rolesModal.style.display = 'none';
      render('settings');
      setTimeout(() => {
        const rbacTab = document.querySelector('[data-settings-tab="rbac"]');
        if (rbacTab) rbacTab.click();
      }, 50);
    });
  });
}

