function initSystemSettingsView(container, defaultTab = 'multiverse') {
  if (!container) return;
  const body = container.querySelector('[data-settings-body]');
  if (!body) return;

  const tabs = container.querySelectorAll('[data-settings-tab]');

  function activateTab(tabName) {
    tabs.forEach(t => t.classList.toggle('active', t.dataset.settingsTab === tabName));
    if (tabName === 'rbac') {
      renderRbacSettingsPanel(body);
    } else {
      body.innerHTML = settingsPanels[tabName] || settingsPanels.multiverse;
      if (tabName === 'inventory-rules') {
        const openShadesBtn = body.querySelector('[data-action="open-cosmetic-shades"]');
        if (openShadesBtn) {
          openShadesBtn.addEventListener('click', () => {
            render('inventory');
            setTimeout(() => {
              if (typeof window.openCosmeticShadesModal === 'function') {
                window.openCosmeticShadesModal();
              } else {
                window.dispatchEvent(new CustomEvent('open-cosmetic-shades-modal'));
              }
            }, 150);
          });
        }

        const openLocksBtn = body.querySelector('[data-action="open-stock-locks"]');
        if (openLocksBtn) {
          openLocksBtn.addEventListener('click', () => {
            render('inventory');
            setTimeout(() => {
              if (typeof window.openStockLocksModal === 'function') {
                window.openStockLocksModal();
              } else {
                window.dispatchEvent(new CustomEvent('open-stock-locks-modal'));
              }
            }, 150);
          });
        }
      }
    }
  }

  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      activateTab(tab.dataset.settingsTab);
    });
  });

  container.querySelectorAll('[data-action="system-settings-back"]').forEach(btn => {
    btn.addEventListener('click', () => {
      render(window.lastNonSettingsScreen || 'inventory');
    });
  });

  container.querySelectorAll('[data-action="save-settings"]').forEach(btn => {
    btn.addEventListener('click', () => {
      showToast('Ajustes del sistema guardados correctamente');
    });
  });

  activateTab(defaultTab);
}

if (settingsBtn) {
  settingsBtn.addEventListener('click', () => {
    render('settings');
  });
}

// 13. ACCIONES INTERACTIVAS Y MODALES DEL ACTION CENTER (HUB 1)
const actionModal = document.querySelector('[data-action-modal]');

function openActionModal(contentHtml) {
  if (!actionModal) return;
  actionModal.innerHTML = contentHtml;
  actionModal.style.display = 'flex';
}

function closeActionModal() {
  if (!actionModal) return;
  actionModal.style.display = 'none';
  actionModal.innerHTML = '';
}

if (actionModal) {
  actionModal.addEventListener('click', (e) => {
    if (e.target === actionModal) {
      closeActionModal();
    }
  });
}

