function openQuickAdjustInventoryModal(sku) {
  const catalogData = {
    'BX-MOD-001': { name: 'Boxer Trunks Modal Seamless', color: 'Negro Carbón', size: 'M', stock: 12, rop: 30, weeklySales: 48, supplier: 'Confección Local (Taller TexMex)', unitCost: 168, leadDays: 3 },
    'JK-ATH-002': { name: 'Jockstrap Athletic Ribbed Band', color: 'Gris Grafito', size: 'G', stock: 14, rop: 28, weeklySales: 32, supplier: 'Confección Local (Taller TexMex)', unitCost: 133, leadDays: 4 },
    'TG-SLK-004': { name: 'Tanga Microfibra Breathable Soft', color: 'Borgoña', size: 'CH', stock: 18, rop: 25, weeklySales: 25, supplier: 'ModaIntima MX', unitCost: 87, leadDays: 5 },
    'BK-FIT-005': { name: 'Bikini Brief Performance Fit', color: 'Azul Marino', size: 'M', stock: 22, rop: 30, weeklySales: 19, supplier: 'Silk & Cotton Iberia', unitCost: 112, leadDays: 7 }
  };

  const item = catalogData[sku] || {
    name: 'Prenda Textil Marte Store',
    color: 'Sólido',
    size: 'M',
    stock: 15,
    rop: 30,
    weeklySales: 20,
    supplier: 'Proveedor Asignado B2B',
    unitCost: 150,
    leadDays: 4
  };

  const suggestedQty = Math.max(30, (item.rop * 2) - item.stock);
  const totalEstCost = suggestedQty * item.unitCost;

  const modalHtml = `
    <div class="modal-dialog max-w-xl shadow-2xl bg-white rounded-2xl overflow-hidden border border-slate-200">
      <div class="modal-header p-5 bg-slate-900 text-white flex items-center justify-between">
        <div>
          <div class="flex items-center gap-2">
            <span class="p-1.5 bg-rose-500/20 text-rose-400 rounded-lg inline-flex">
              <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
            </span>
            <h3 class="text-base font-bold text-white">Reabastecimiento Rápido: ${sku}</h3>
          </div>
          <p class="text-xs text-slate-300 mt-1">Generación de orden de reposición inmediata para evitar quiebre de stock.</p>
        </div>
        <button type="button" class="text-slate-400 hover:text-white p-1 rounded-lg hover:bg-slate-800 transition cursor-pointer" onclick="closeActionModal()">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
        </button>
      </div>

      <div class="p-5 space-y-4">
        <!-- Resumen del Producto -->
        <div class="p-3.5 bg-slate-50 border border-slate-200/80 rounded-xl flex items-center justify-between">
          <div>
            <div class="font-bold text-slate-900 text-sm">${item.name}</div>
            <div class="text-xs text-slate-500 mt-0.5 font-mono">SKU: ${sku} &bull; Talla: <span class="font-bold text-slate-800">${item.size}</span> &bull; Color: ${item.color}</div>
            <div class="text-[11px] text-indigo-600 mt-0.5">Proveedor: ${item.supplier} (Lead Time: ${item.leadDays} días)</div>
          </div>
          <div class="text-right">
            <span class="px-2.5 py-1 rounded-full text-xs font-black bg-rose-100 text-rose-700 border border-rose-200">
              ${item.stock} pzs en stock
            </span>
            <div class="text-[10px] text-slate-500 mt-1">Punto Reorden (ROP): ${item.rop} pzs</div>
          </div>
        </div>

        <!-- Parámetros de la Orden -->
        <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <div class="p-3 bg-white border border-slate-200 rounded-xl">
            <label class="text-[11px] font-bold text-slate-600 uppercase block mb-1">Cantidad a Reordenar</label>
            <input type="number" id="quick-reorder-qty" class="w-full px-3 py-2 text-sm font-bold border border-slate-300 rounded-lg bg-slate-50 text-slate-900 focus:bg-white focus:border-indigo-500 focus:outline-none" value="${suggestedQty}" min="10" step="5">
            <span class="text-[10px] text-slate-400 mt-1 block">Sugerido para cubrir 2 semanas de demanda</span>
          </div>

          <div class="p-3 bg-white border border-slate-200 rounded-xl">
            <span class="text-[11px] font-bold text-slate-600 uppercase block mb-1">Presupuesto Estimado</span>
            <div class="text-xl font-black text-slate-900 font-mono mt-1">$${totalEstCost.toLocaleString()} MXN</div>
            <span class="text-[10px] text-slate-500 mt-1 block">Costo unitario: $${item.unitCost} MXN / pz</span>
          </div>
        </div>

        <div class="p-3 bg-amber-50 border border-amber-200 rounded-xl text-xs text-amber-800">
          <strong>Impacto en SLA:</strong> Al generar esta orden ahora, el proveedor despacha en ${item.leadDays} días hábiles, evitando 36 horas de desabasto local.
        </div>
      </div>

      <div class="modal-footer p-4 bg-slate-50 border-t border-slate-200 flex items-center justify-between">
        <button type="button" class="px-3.5 py-2 bg-slate-200 hover:bg-slate-300 text-slate-700 text-xs font-semibold rounded-xl transition cursor-pointer" onclick="closeActionModal()">
          Cancelar
        </button>
        <div class="flex items-center gap-2">
          <button type="button" data-action="confirm-quick-stock-adjust" data-sku="${sku}" class="px-3 py-2 bg-slate-800 hover:bg-slate-700 text-white text-xs font-semibold rounded-xl transition cursor-pointer">
            Ajustar Stock Físico
          </button>
          <button type="button" data-action="confirm-quick-po" data-sku="${sku}" class="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold rounded-xl transition cursor-pointer flex items-center gap-1.5 shadow-sm">
            <span>Generar Orden Inmediata</span>
            <span>&rarr;</span>
          </button>
        </div>
      </div>
    </div>
  `;

  openActionModal(modalHtml);
}

