function updateRampDiscrepancyPreview(totalPieces, unitCostMxn) {
  const goodEl = document.getElementById('rampGoodQty');
  const damagedEl = document.getElementById('rampDamagedQty');
  const defectRow = document.getElementById('rampDefectRow');
  const finPreview = document.getElementById('rampFinancialPreview');
  if (!goodEl || !damagedEl || !defectRow) return;

  const good = parseInt(goodEl.value, 10) || 0;
  const damaged = parseInt(damagedEl.value, 10) || 0;

  if (damaged > 0) {
    defectRow.classList.remove('hidden');
    const deduction = damaged * (unitCostMxn || 150);
    const netPayable = (totalPieces * (unitCostMxn || 150)) - deduction;
    if (finPreview) {
      finPreview.innerHTML = `Deducción por merma: <strong>-$${deduction.toLocaleString()} MXN</strong>. Saldo neto a autorizar en Hub 5: <strong>$${netPayable.toLocaleString()} MXN</strong>. Se retendrá la dispersión SPEI hasta emitir Nota de Débito.`;
    }
  } else {
    defectRow.classList.add('hidden');
    if (finPreview) finPreview.innerHTML = '';
  }
}

function confirmRampReceipt(taskId) {
  const task = (typeof taskId === 'string')
    ? (operationalState.tasks.find(t => t.id === taskId) || operationalState.tasks.find(t => t.actionKey === 'open-ramp-dock'))
    : operationalState.tasks.find(t => t.actionKey === 'open-ramp-dock');

  const d = (task && task.data) ? task.data : {
    poCode: 'OC-2026-088',
    supplierId: 'VND-TORZO',
    supplierName: 'Torzo Labs & Textile Co.',
    carrierName: 'Fletera Potosinos Express',
    trackingNumber: 'POT-8831920',
    remissionNumber: 'REM-4491',
    totalPieces: 150,
    productName: 'Bóxer Ergonómico Modal & Spandex Microfibra',
    sku: 'TRZ-BOXER-NEO',
    unitCostMxn: 150.00,
    totalAmountMxn: 22500.00
  };

  const goodInput = document.getElementById('rampGoodQty');
  const damagedInput = document.getElementById('rampDamagedQty');
  const defectReasonEl = document.getElementById('rampDefectReason');
  const notesInput = document.getElementById('rampNotes');

  const goodQty = goodInput ? (parseInt(goodInput.value, 10) || 0) : (d.goodQty !== undefined ? d.goodQty : d.totalPieces);
  const damagedQty = damagedInput ? (parseInt(damagedInput.value, 10) || 0) : (d.damagedQty !== undefined ? d.damagedQty : 0);
  const defectReason = (defectReasonEl && damagedQty > 0) ? defectReasonEl.value : (damagedQty > 0 ? 'Defecto detectado en rampa' : null);
  const notes = notesInput ? notesInput.value : '';

  const unitCost = d.unitCostMxn || 150.00;
  const totalAmount = d.totalAmountMxn || (d.totalPieces * unitCost);
  const debitNoteAmount = damagedQty * unitCost;
  const netPayable = totalAmount - debitNoteAmount;
  const inspector = 'Carlos Almacén (Rampa Central)';

  // 1. Marcar tarea completada en Hub 1
  if (task) task.status = 'completed';
  operationalState.kpis.inboundTransit = Math.max(0, (operationalState.kpis.inboundTransit || 1) - 1);

  operationalState.completedLog.unshift({
    id: 'log-' + Date.now(),
    time: getFormattedTime(),
    title: `Recepción en Rampa ${d.remissionNumber}: ${goodQty} conformes, ${damagedQty} defectuosas de ${d.poCode} (${d.carrierName})`,
    operator: inspector,
    category: 'Recepcion'
  });

  // 2. Registrar asiento inmutable en Kardex
  window.inventoryKardex = window.inventoryKardex || [];
  window.inventoryKardex.unshift({
    id: `kardex-ramp-${Date.now()}`,
    timestamp: new Date().toISOString(),
    type: 'ENTRADA_RAMPA_PROVEEDOR',
    poCode: d.poCode,
    remissionNumber: d.remissionNumber,
    sku: d.sku,
    productName: d.productName,
    goodQty: goodQty,
    damagedQty: damagedQty,
    totalQty: goodQty + damagedQty,
    operator: inspector,
    carrierName: d.carrierName,
    trackingNumber: d.trackingNumber,
    notes: notes || `Recepción en rampa de fletera ${d.carrierName}`
  });

  // 3. Alimentar en automático el Cotejo de 3 Vías Inbound (Hub 5 Finanzas)
  let match = financeState.threeWayMatches.find(m => m.poCode === d.poCode);
  if (!match) {
    match = {
      id: 'twm-' + (financeState.threeWayMatches.length + 1).toString().padStart(2, '0'),
      poCode: d.poCode,
      supplierId: d.supplierId || 'VND-TORZO',
      supplierName: d.supplierName || 'Torzo Labs & Textile Co.',
      poQty: d.totalPieces,
      poUnitPrice: unitCost,
      poTotalAmount: totalAmount,
      warehouseReceivedQty: goodQty + damagedQty,
      warehouseGoodQty: goodQty,
      warehouseDamagedQty: damagedQty,
      invoiceNumber: `FAC-TRZ-${d.remissionNumber.replace(/[^0-9]/g, '') || '901'}`,
      invoiceQty: d.totalPieces,
      invoiceGrossAmount: totalAmount,
      matchStatus: damagedQty > 0 ? 'discrepancy_held' : 'matched',
      speiPayoutBlocked: damagedQty > 0,
      discrepancyReason: damagedQty > 0 ? `${damagedQty} prendas mermadas en rampa de llegada (${defectReason}). Dispersión SPEI bloqueada.` : null,
      debitNoteNumber: null,
      debitNoteAmount: debitNoteAmount,
      payableNetAmount: netPayable,
      inspectedBy: inspector,
      updatedAt: 'Hoy, ' + getFormattedTime()
    };
    financeState.threeWayMatches.unshift(match);
  } else {
    match.warehouseReceivedQty = goodQty + damagedQty;
    match.warehouseGoodQty = goodQty;
    match.warehouseDamagedQty = damagedQty;
    match.inspectedBy = inspector;
    match.updatedAt = 'Hoy, ' + getFormattedTime();
    if (damagedQty > 0) {
      match.matchStatus = 'discrepancy_held';
      match.speiPayoutBlocked = true;
      match.debitNoteAmount = debitNoteAmount;
      match.payableNetAmount = netPayable;
      match.discrepancyReason = `${damagedQty} prendas mermadas con defecto en rampa de llegada (${defectReason}). Dispersión SPEI bloqueada.`;
    } else {
      match.matchStatus = 'matched';
      match.speiPayoutBlocked = false;
      match.debitNoteAmount = 0.00;
      match.payableNetAmount = totalAmount;
      match.discrepancyReason = null;
    }
  }

  // 4. Actualizar estado en Extranet Proveedores (vendorPortalState)
  const vOrder = vendorPortalState.orders.find(o => o.poCode === d.poCode);
  if (vOrder) {
    vOrder.productionStatus = 'delivered';
    vOrder.productionStatusLabel = damagedQty > 0 ? 'Entregado en Rampa (Con Mermas)' : 'Entregado en Rampa (100% Conforme)';
    vOrder.threeWayStatus = damagedQty > 0 ? 'discrepancy_held' : 'matched';
    vOrder.dockFeedback = damagedQty > 0
      ? `${goodQty} piezas aprobadas, ${damagedQty} piezas mermadas (${defectReason}).`
      : `${goodQty} piezas aprobadas conforme a orden de compra.`;
    vOrder.debitNoteSuggested = debitNoteAmount;
    vOrder.netPayableMxn = netPayable;
  }

  closeActionModal();

  const toastMessage = damagedQty > 0
    ? `Recepción en Rampa ${d.remissionNumber}: ${goodQty} conformes y ${damagedQty} mermas. Cotejo 3 Vías en Hub 5 retenido preventivamente para Nota de Débito.`
    : `Recepción en Rampa ${d.remissionNumber}: ${goodQty} piezas conformes ingresadas a Kardex. Cotejo 3 Vías 100% cuadrado en Hub 5.`;
  showToast(toastMessage);

  const currentScr = (typeof currentScreen !== 'undefined') ? currentScreen : 'dashboard';
  render(currentScr);
}

