function saveDiscrepancyNotes(taskId) {
  const targetId = taskId || 'task-inbound-003';
  const notesInput = document.getElementById('discrepancy-notes-input');
  const text = notesInput ? notesInput.value.trim() : '';

  if (!operationalState.purchasesAgreements) {
    operationalState.purchasesAgreements = {};
  }

  operationalState.purchasesAgreements[targetId] = {
    ...(operationalState.purchasesAgreements[targetId] || {}),
    draft: text,
    savedAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    status: operationalState.purchasesAgreements[targetId]?.status === 'formalized' ? 'formalized' : 'draft'
  };

  showToast('Borrador de acuerdo con proveedor guardado para despues.');
  closeActionModal();
}

