function sendFormalDiscrepancyEmail(taskId) {
  const targetId = taskId || 'task-inbound-003';
  const task = operationalState.tasks.find(t => t.id === targetId) || operationalState.tasks[0];
  const d = task ? task.data : { ocId: '#OC-2026-003' };

  if (!operationalState.purchasesAgreements) {
    operationalState.purchasesAgreements = {};
  }

  const emailToInput = document.getElementById('email-to-input');
  const recipient = emailToInput ? emailToInput.value : 'f.torzo@torzomayoreo.com';

  operationalState.purchasesAgreements[targetId] = {
    ...(operationalState.purchasesAgreements[targetId] || {}),
    status: 'formalized',
    sentAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    recipient: recipient
  };

  // Agregar a la bitacora oficial del turno
  operationalState.completedLog.unshift({
    title: `Formalizacion de Discrepancia PO ${d.ocId || '#OC-2026-003'} (Nota de Credito -$2,250)`,
    operator: 'Elena Compras',
    category: 'Compras & Proveedores',
    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  });

  closeActionModal();
  showToast(`Correo de formalizacion enviado exitosamente a ${recipient} con acta PDF adjunta.`);
  render('dashboard');
}

