function confirmShippingClaim(trackingNumber) {
  const sa = financeState.shippingAudit;
  const record = sa.records.find(r => r.trackingNumber === trackingNumber);
  if (!record) return;

  const notesEl = document.getElementById('claimTechnicalNotesInput');
  const notes = notesEl ? notesEl.value : '';

  const claimFolio = `CLAIM-${record.carrierId.toUpperCase()}-2026-${Math.floor(100 + Math.random() * 900)}`;
  record.auditStatus = 'claim_filed';
  record.claimFolio = claimFolio;
  record.claimNotes = notes;

  // Registrar retención preventiva en cuentas por pagar si existe factura courier
  const courierBill = financeState.vendorBills.find(b => b.category === 'courier_freight');
  if (courierBill) {
    courierBill.notes = (courierBill.notes || '') + ` [Retención ${claimFolio}: -$${record.overchargeMxn.toFixed(2)} MXN en aclaración]`;
  }

  closeActionModal();
  showToast(`Reclamación ${claimFolio} emitida para guía ${record.trackingNumber}. Retención preventiva de $${record.overchargeMxn.toFixed(2)} MXN aplicada.`);
  render('finance');
}

