// 13.6 MODAL DE CORRECCIÓN Y VALIDACIÓN PREDICTIVA DE DIRECCIÓN POSTAL (TASK-DSH-01, TASK-DSH-06)
function openSalesAddressModal(caseId) {
  const item = salesState.items.find(i => i.id === caseId);
  if (!item) return;

  const addr = item.addressData || {
    street: 'Av. Insurgentes Sur',
    extNumber: '',
    intNumber: 'Piso 4, Int B',
    postalCode: '03100',
    colonia: 'Del Valle Sur',
    municipality: 'Benito Juarez',
    state: 'Ciudad de Mexico',
    courier: 'DHL Express'
  };

  const initialVal = validateAddressPredictive(addr);
  const orderId = item.contextData ? item.contextData.orderId : 'Pedido';

  const colOptions = initialVal.suggestedColonias.length > 0
    ? initialVal.suggestedColonias.map(c => `<option value="${c}" ${c.toLowerCase() === (addr.colonia || '').toLowerCase() ? 'selected' : ''}>${c}</option>`).join('')
    : `<option value="${addr.colonia || ''}">${addr.colonia || 'Sin colonia'}</option>`;

  const modalHtml = `
    <div class="modal-dialog max-w-lg shadow-2xl">
      <div class="modal-header">
        <div class="flex items-center gap-2">
          <span class="action-badge address">Dirección</span>
          <h3 class="text-sm font-black uppercase tracking-wider text-slate-800">Validar Domicilio: ${orderId}</h3>
          <button class="section-help-btn" type="button" aria-label="Ayuda de Direcciones" data-help-title="Validacion Postal Sepomex" data-help-desc="Validador predictivo contra el catalogo oficial Sepomex y reglas de cobertura DHL Express / Estafeta para evitar devoluciones y sobrecostos por zona extendida.">?</button>
        </div>
        <button class="close-icon-btn" data-action="close-action-modal" aria-label="Cerrar modal">
          <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 6 6 18M6 6l12 12"/></svg>
        </button>
      </div>

      <div class="modal-body p-4 space-y-3">
        <!-- Caja Dinamica de Estatus Sepomex -->
        <div id="postal-status-container">
          <div class="postal-status-box ${initialVal.status}">
            <div class="flex items-center justify-between gap-2 mb-1">
              <span class="postal-score-badge ${initialVal.status}">${initialVal.score}% Fiabilidad</span>
              <span class="postal-zone-tag ${initialVal.coverage === 'extended_zone' ? 'extended' : ''}">${initialVal.courierNote}</span>
            </div>
            <div class="font-medium text-xs">${initialVal.message}</div>
            ${initialVal.issues.length > 0 ? `<ul class="list-disc list-inside mt-1 space-y-0.5">${initialVal.issues.map(i => `<li>${i}</li>`).join('')}</ul>` : ''}
            ${initialVal.warnings.length > 0 ? `<ul class="list-disc list-inside mt-1 text-[11px] space-y-0.5">${initialVal.warnings.map(w => `<li>${w}</li>`).join('')}</ul>` : ''}
          </div>
        </div>

        <div class="grid grid-cols-2 gap-3 text-xs">
          <div class="col-span-2">
            <label class="block text-slate-500 font-bold mb-1">Calle / Avenida:</label>
            <input type="text" id="addr-street" class="w-full px-3 py-1.5 border border-slate-300 rounded text-xs" value="${addr.street || ''}">
          </div>
          <div>
            <label class="block text-slate-500 font-bold mb-1">Número Exterior (Obligatorio):</label>
            <input type="text" id="addr-ext" class="w-full px-3 py-1.5 border border-indigo-400 rounded text-xs bg-indigo-50/40 font-bold" value="${addr.extNumber || ''}" placeholder="Ej: 1048">
          </div>
          <div>
            <label class="block text-slate-500 font-bold mb-1">Número Interior / Depto:</label>
            <input type="text" id="addr-int" class="w-full px-3 py-1.5 border border-slate-300 rounded text-xs" value="${addr.intNumber || ''}" placeholder="Opcional">
          </div>
          <div>
            <label class="block text-slate-500 font-bold mb-1">Código Postal:</label>
            <input type="text" id="addr-zip" class="w-full px-3 py-1.5 border border-slate-300 rounded text-xs font-mono font-bold" value="${addr.postalCode || ''}" maxlength="5" placeholder="Ej: 03100">
          </div>
          <div>
            <label class="block text-slate-500 font-bold mb-1">Colonia / Asentamiento:</label>
            <select id="addr-col" class="w-full px-3 py-1.5 border border-slate-300 rounded text-xs bg-white">
              ${colOptions}
            </select>
          </div>
          <div>
            <label class="block text-slate-500 font-bold mb-1">Municipio / Alcaldía:</label>
            <input type="text" id="addr-city" class="w-full px-3 py-1.5 border border-slate-300 rounded text-xs bg-slate-50" value="${addr.municipality || ''}" readonly>
          </div>
          <div>
            <label class="block text-slate-500 font-bold mb-1">Estado:</label>
            <input type="text" id="addr-state" class="w-full px-3 py-1.5 border border-slate-300 rounded text-xs bg-slate-50" value="${addr.state || ''}" readonly>
          </div>
        </div>

        <div class="p-3 bg-slate-50 border border-slate-200 rounded text-xs text-slate-600 flex items-center justify-between">
          <span class="flex items-center gap-1.5 font-medium">
            <svg class="w-4 h-4 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/></svg>
            <span>Validación predictiva Sepomex: Cobertura DHL Express confirmada.</span>
          </span>
        </div>
      </div>

      <div class="modal-footer p-4 bg-slate-50 border-t border-slate-200 flex justify-end gap-2">
        <button class="button button-light" data-action="close-action-modal">Cancelar</button>
        <button class="button button-quiet" data-confirm-fix-address data-case-id="${item.id}" style="background: #080808; color: #fff;">
          Validar Domicilio & Liberar a Almacén
        </button>
      </div>
    </div>
  `;

  openActionModal(modalHtml);

  // Escuchas reactivas en vivo para actualizacion instantanea
  const getModalEl = (id) => {
    if (typeof document === 'undefined') return null;
    if (typeof document.getElementById === 'function') return document.getElementById(id);
    if (typeof document.querySelector === 'function') return document.querySelector('#' + id);
    return null;
  };

  const zipInput = getModalEl('addr-zip');
  const extInput = getModalEl('addr-ext');
  const streetInput = getModalEl('addr-street');
  const colSelect = getModalEl('addr-col');
  const cityInput = getModalEl('addr-city');
  const stateInput = getModalEl('addr-state');
  const statusBox = getModalEl('postal-status-container');

  function updatePostalUi() {
    if (!statusBox || !zipInput) return;
    const currentZip = (zipInput.value || '').trim();
    const currentExt = (extInput ? extInput.value : '').trim();
    const currentStreet = (streetInput ? streetInput.value : '').trim();
    const currentCol = (colSelect ? colSelect.value : '').trim();

    if (/^\d{5}$/.test(currentZip) && SEPOMEX_CATALOG[currentZip]) {
      const entry = SEPOMEX_CATALOG[currentZip];
      if (cityInput) cityInput.value = entry.municipality;
      if (stateInput) stateInput.value = entry.state;
      if (colSelect && colSelect.dataset.lastZip !== currentZip) {
        colSelect.dataset.lastZip = currentZip;
        colSelect.innerHTML = entry.colonias.map(c => `<option value="${c}">${c}</option>`).join('');
      }
    }

    const res = validateAddressPredictive({
      street: currentStreet,
      extNumber: currentExt,
      postalCode: currentZip,
      colonia: colSelect ? colSelect.value : currentCol,
      municipality: cityInput ? cityInput.value : '',
      state: stateInput ? stateInput.value : ''
    });

    statusBox.innerHTML = `
      <div class="postal-status-box ${res.status}">
        <div class="flex items-center justify-between gap-2 mb-1">
          <span class="postal-score-badge ${res.status}">${res.score}% Fiabilidad</span>
          <span class="postal-zone-tag ${res.coverage === 'extended_zone' ? 'extended' : ''}">${res.courierNote}</span>
        </div>
        <div class="font-medium text-xs">${res.message}</div>
        ${res.issues.length > 0 ? `<ul class="list-disc list-inside mt-1 space-y-0.5">${res.issues.map(i => `<li>${i}</li>`).join('')}</ul>` : ''}
        ${res.warnings.length > 0 ? `<ul class="list-disc list-inside mt-1 text-[11px] space-y-0.5">${res.warnings.map(w => `<li>${w}</li>`).join('')}</ul>` : ''}
      </div>
    `;
  }

  if (zipInput && zipInput.addEventListener) zipInput.addEventListener('input', updatePostalUi);
  if (extInput && extInput.addEventListener) extInput.addEventListener('input', updatePostalUi);
  if (streetInput && streetInput.addEventListener) streetInput.addEventListener('input', updatePostalUi);
  if (colSelect && colSelect.addEventListener) colSelect.addEventListener('change', updatePostalUi);
}

