    const task = operationalState.tasks.find(t => t.id === taskId) || operationalState.tasks.find(t => t.category === 'empaque');
    if (task) task.status = 'completed';
    operationalState.kpis.pendingPacking = Math.max(0, (operationalState.kpis.pendingPacking || 1) - 1);
    if (taskId === 'task-pack-1048') {
      operationalState.kpis.mixedCartsReady = Math.max(0, (operationalState.kpis.mixedCartsReady || 1) - 1);
    }
    const orderLabel = (task && task.data && task.data.orderId) ? task.data.orderId : '#MIX-1048';
    const courier = (task && task.data && task.data.courier) ? task.data.courier : 'DHL Express';

    // TASK-INT-04: Verificacion obligatoria de preferencias si es suscriptor
    const subPrefs = task && task.data ? task.data.subscriberPreferences : null;
    const prefCheck = document.getElementById('chk-pref-verified');
    if (subPrefs && prefCheck && !prefCheck.checked) {
      showToast('Debes cotejar y marcar la verificacion de preferencias de suscriptor antes de empaquetar.', 'error');
      return;
    }

    // TASK-INT-02: Transicion de Comprometido a Despachado & Asiento en Kardex (SALIDA_VENTA)
    const itemsToDispatch = (task && task.data && task.data.items && task.data.items.length)
      ? task.data.items.map(it => ({
          sku: it.sku,
          name: it.name,
          qty: it.qty || 1,
          size: (it.name && it.name.includes('Talla M')) ? 'm' : (it.size || 'm')
        }))
      : [
          { sku: 'BOX-BAM-001-M', name: 'Boxer Bamboo Negro - Talla M', qty: 2, size: 'm' },
          { sku: 'TOR-DRP-002-M', name: 'Jockstrap Athletic Carbon - Talla M', qty: 1, size: 'm' },
          { sku: 'ACC-BAG-001', name: 'Bolsa de Lavado Delicada', qty: 1, size: 'unit' }
        ];

    dispatchOrderFulfillment({
      orderId: orderLabel,
      taskId: taskId,
      operator: currentRole.name,
      courier: courier,
      subscriberPreferences: subPrefs,
      items: itemsToDispatch,
      timestamp: new Date().toISOString()
    });

    const logTitle = (subPrefs && subPrefs.isSubscriber)
      ? `Pedido suscriptor ${orderLabel} empacado con preferencias auditadas (${subPrefs.sizePreference ? 'Talla ' + subPrefs.sizePreference.toUpperCase() : ''}) para ${courier}`
      : `Pedido ${orderLabel} empacado y transferido a Kardex (SALIDA_VENTA) para ${courier}`;

    operationalState.completedLog.unshift({
      id: 'log-' + Date.now(),
      time: getFormattedTime(),
      title: logTitle,
      operator: currentRole.name,
      category: 'Empaque'
    });
    closeActionModal();
    const toastMsg = (subPrefs && subPrefs.isSubscriber)
      ? `Pedido ${orderLabel} empacado con exito. Preferencias de suscriptor auditadas y descontadas en Kardex.`
      : `Pedido ${orderLabel} empacado y descontado en Kardex. Listo para recolecta.`;
    showToast(toastMsg);
    const activeLink = document.querySelector('.module-link.active');
    if (activeLink && activeLink.dataset.screen === 'dashboard') {
      render('dashboard');
    }
