    const task = operationalState.tasks.find(t => t.id === taskId) || operationalState.tasks.find(t => t.category === 'expedicion');
    if (task) task.status = 'completed';
    const count = (task && task.data && task.data.packageCount) ? task.data.packageCount : 6;
    const courier = (task && task.data && task.data.courier) ? task.data.courier : 'DHL Express';

