// ==========================================================================
// 15. MOTOR DE TOOLTIPS CONTEXTUALES DE SECCIÓN CON '?' (REGLA 8)
// ==========================================================================
const sectionTooltipEl = document.querySelector('[data-section-tooltip]');
let activeTooltipBtn = null;
let tooltipTimeout = null;

function showSectionTooltip(btn) {
  if (!sectionTooltipEl || !btn) return;
  const title = btn.dataset.helpTitle || 'Ayuda de Seccion';
  const desc = btn.dataset.helpDesc || '';
  if (!desc) return;

  const titleEl = sectionTooltipEl.querySelector('[data-tooltip-title]');
  const bodyEl = sectionTooltipEl.querySelector('[data-tooltip-body]');
  if (titleEl) titleEl.textContent = title;
  if (bodyEl) bodyEl.textContent = desc;

  sectionTooltipEl.style.display = 'block';
  sectionTooltipEl.classList.remove('arrow-top', 'arrow-bottom');

  const rect = btn.getBoundingClientRect();
  const tipRect = sectionTooltipEl.getBoundingClientRect();

  // Posicion vertical: preferir arriba; si no cabe en pantalla, colocar abajo
  let top = rect.top - tipRect.height - 8;
  if (top < 12) {
    top = rect.bottom + 8;
    sectionTooltipEl.classList.add('arrow-top');
  } else {
    sectionTooltipEl.classList.add('arrow-bottom');
  }

  // Posicion horizontal: centrado respecto al boton
  let left = rect.left + (rect.width / 2) - (tipRect.width / 2);
  if (left < 12) left = 12;
  if (left + tipRect.width > window.innerWidth - 12) {
    left = window.innerWidth - tipRect.width - 12;
  }

  // Ajustar flecha
  const arrowEl = sectionTooltipEl.querySelector('[data-tooltip-arrow]');
  if (arrowEl) {
    const arrowLeft = rect.left + (rect.width / 2) - left - 4;
    arrowEl.style.left = `${Math.max(10, Math.min(tipRect.width - 18, arrowLeft))}px`;
  }

  sectionTooltipEl.style.top = `${Math.round(top)}px`;
  sectionTooltipEl.style.left = `${Math.round(left)}px`;
  sectionTooltipEl.classList.add('show');
  btn.classList.add('active');
  activeTooltipBtn = btn;
}

function hideSectionTooltip() {
  if (!sectionTooltipEl) return;
  sectionTooltipEl.classList.remove('show');
  sectionTooltipEl.style.display = 'none';
  if (activeTooltipBtn) {
    activeTooltipBtn.classList.remove('active');
    activeTooltipBtn = null;
  }
}

// Event Delegation para tooltips (hover + focus + click/tap)
document.addEventListener('mouseover', (e) => {
  const btn = e.target.closest('.section-help-btn');
  if (btn) {
    clearTimeout(tooltipTimeout);
    showSectionTooltip(btn);
  }
});

document.addEventListener('mouseout', (e) => {
  const btn = e.target.closest('.section-help-btn');
  if (btn && (!activeTooltipBtn || !activeTooltipBtn.dataset.pinned)) {
    tooltipTimeout = setTimeout(hideSectionTooltip, 120);
  }
});

document.addEventListener('click', (e) => {
  const btn = e.target.closest('.section-help-btn');
  if (btn) {
    e.stopPropagation();
    if (activeTooltipBtn === btn && btn.dataset.pinned === 'true') {
      delete btn.dataset.pinned;
      hideSectionTooltip();
    } else {
      if (activeTooltipBtn) delete activeTooltipBtn.dataset.pinned;
      btn.dataset.pinned = 'true';
      showSectionTooltip(btn);
    }
  } else if (!e.target.closest('[data-section-tooltip]')) {
    if (activeTooltipBtn) delete activeTooltipBtn.dataset.pinned;
    hideSectionTooltip();
  }
});

document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    if (activeTooltipBtn) delete activeTooltipBtn.dataset.pinned;
    hideSectionTooltip();
  }
});

if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
  window.addEventListener('scroll', () => {
    if (activeTooltipBtn && !activeTooltipBtn.dataset.pinned) {
      hideSectionTooltip();
    } else if (activeTooltipBtn && activeTooltipBtn.dataset.pinned) {
      showSectionTooltip(activeTooltipBtn);
    }
  }, { passive: true });
}

