// Helper de elemento principal para Hub 7
function getAlliesMainEl() {
  return document.querySelector('[data-main]') || document.getElementById('mainContent') || document.querySelector('main');
}

// 2. Privacidad de Prospectos: Data Masking de telefonos (ej. "55 **** 1290")
function maskPhoneNumber(phone) {
  if (!phone) return '';
  const digits = String(phone).replace(/[^\d]/g, '');
  if (digits.length < 8) return '**** ' + digits.slice(-4);
  const prefix = digits.length >= 10 ? digits.slice(-10, -8) : digits.slice(0, 2);
  const last4 = digits.slice(-4);
  return `${prefix} **** ${last4}`;
}

// 4. Logica de Liquidacion: Servicio de calculo de compensacion cruzada
function calculateAllyClearingBalance(allyId) {
  const targetId = allyId ? Number(allyId) : alliesState.selectedAllyId;
  const ally = alliesState.alliesList.find(a => a.id === targetId) || alliesState.alliesList[0];
  const leadsCredit = ally.stats.leadsReceived * ally.leadAcquisitionCost;
  const commissionsDebit = ally.stats.commissionEarned;
  const netBalance = leadsCredit - commissionsDebit;
  return {
    allyId: ally.id,
    allyName: ally.name,
    leadsReceived: ally.stats.leadsReceived,
    leadAcquisitionCost: ally.leadAcquisitionCost,
    leadsCredit: leadsCredit,
    ordersAttributed: ally.stats.ordersAttributed,
    gmvAttributed: ally.stats.gmvAttributed,
    commissionRate: ally.commissionRate,
    commissionsDebit: commissionsDebit,
    netBalance: netBalance,
    formula: `(${ally.stats.leadsReceived} leads x $${ally.leadAcquisitionCost.toFixed(2)}) - $${commissionsDebit.toFixed(2)} = ${netBalance >= 0 ? '+' : '-'}$${Math.abs(netBalance).toFixed(2)} MXN`,
    payableBy: netBalance < 0 ? 'marte_store' : (netBalance > 0 ? 'ally' : 'settled')
  };
}

// 1. Seguridad por Token: Acceso unico sin contrasena restringido a datos propios
function accessPortalByToken(token) {
  if (!token) return false;
  const cleanToken = token.trim();
  const ally = alliesState.alliesList.find(a => a.portalToken === cleanToken);
  if (!ally) {
    if (typeof showToast === 'function') showToast('Token criptografico no valido o revocado.');
    return false;
  }
  alliesState.viewMode = 'partner';
  alliesState.activeAdminTab = 'partner_portal';
  alliesState.selectedAllyId = ally.id;
  alliesState.tokenRestrictedMode = true;
  alliesState.tokenRestrictedAllyId = ally.id;
  const main = getAlliesMainEl();
  if (main) main.innerHTML = alliesBody();
  if (typeof showToast === 'function') {
    showToast(`Acceso autorizado por token para ${ally.name} (Modo Lectura Restringida).`);
  }
  return true;
}

function exitTokenRestrictedMode() {
  alliesState.tokenRestrictedMode = false;
  alliesState.tokenRestrictedAllyId = null;
  alliesState.viewMode = 'admin';
  alliesState.activeAdminTab = 'directory';
  const main = getAlliesMainEl();
  if (main) main.innerHTML = alliesBody();
  if (typeof showToast === 'function') {
    showToast('Sesion de token finalizada. Regresando a consola RevOps.');
  }
}

// 3. Exportacion Limpia en CSV con Data Masking para taquilla
function exportAlliesDoorListCsv(allyId) {
  const targetId = allyId ? Number(allyId) : alliesState.selectedAllyId;
  const ally = alliesState.alliesList.find(a => a.id === targetId) || alliesState.alliesList[0];
  const leads = alliesState.leadCaptures.filter(l => l.allyId === ally.id);

  const headers = [
    'Folio Voucher',
    'Nombre Asistente',
    'Telefono (Data Masking)',
    'Universo',
    'Estado Canje',
    'Fecha Registro',
    'Hora Canje Taquilla',
    'Staff Puerta',
    'Score Meta CAPI'
  ];

  const rows = leads.map(l => [
    `"${l.voucherCode}"`,
    `"${l.leadName.replace(/"/g, '""')}"`,
    `"${maskPhoneNumber(l.leadWhatsapp)}"`,
    `"${l.universe.toUpperCase()}"`,
    `"${l.isRedeemed ? 'CANJEADO' : 'PENDIENTE'}"`,
    `"${l.date}"`,
    `"${l.redeemedAt || 'N/A'}"`,
    `"${(l.redeemedBy || 'N/A').replace(/"/g, '""')}"`,
    `"${l.capiScore.toFixed(2)}/10"`
  ]);

  const csvContent = '\uFEFF' + [headers.join(','), ...rows.map(r => r.join(','))].join('\r\n');

  if (typeof window !== 'undefined' && typeof document !== 'undefined' && document.createElement) {
    try {
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.setAttribute('href', url);
      link.setAttribute('download', `lista_taquilla_${ally.code.toLowerCase()}_${new Date().toISOString().slice(0, 10)}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } catch (e) {
      // Entorno sin soporte de descargas DOM directas
    }
  }

  if (typeof showToast === 'function') {
    showToast(`Lista de taquilla descargada en CSV (${leads.length} asistentes protegidos) para ${ally.name}.`);
  }

  return csvContent;
}

function renderTicketValidationResultHtml(res) {
  if (!res) return '';
  if (res.status === 'success') {
    return `
      <div class="ticket-result-success">
        <div class="flex items-center gap-2 font-bold text-sm">
          <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
          <span>Acceso Válido - Beneficio Aprobado</span>
        </div>
        <p class="text-xs mt-1 text-emerald-200">${res.message}</p>
        <div class="mt-2 pt-2 border-t border-emerald-800/80 text-[11px] text-emerald-300 flex items-center justify-between">
          <span>Registrado a las: <strong>${res.voucher ? res.voucher.redeemedAt : ''}</strong></span>
          <span>Meta CAPI EMQ: <strong>${res.voucher ? res.voucher.capiScore.toFixed(1) : '9.8'}/10</strong></span>
        </div>
      </div>
    `;
  } else if (res.status === 'already_redeemed') {
    return `
      <div class="ticket-result-error">
        <div class="flex items-center gap-2 font-bold text-sm">
          <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
          <span>Código Ya Canjeado (Prevención de Reuso)</span>
        </div>
        <p class="text-xs mt-1 text-rose-200">${res.message}</p>
      </div>
    `;
  } else {
    return `
      <div class="ticket-result-error">
        <div class="flex items-center gap-2 font-bold text-sm">
          <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>
          <span>Código Inválido</span>
        </div>
        <p class="text-xs mt-1 text-rose-200">${res.message}</p>
      </div>
    `;
  }
}

