function validateTicketVoucher(code) {
  if (!code || !code.trim()) {
    alliesState.lastValidationResult = { status: 'error', message: 'Por favor ingresa un código de voucher válido.' };
  } else {
    const cleanCode = code.trim().toUpperCase();
    const voucher = alliesState.leadCaptures.find(v => v.voucherCode === cleanCode);

    if (!voucher) {
      alliesState.lastValidationResult = {
        status: 'error',
        code: cleanCode,
        message: `Código no encontrado: "${cleanCode}". Verifica que pertenezca a este evento o convenio.`
      };
    } else if (voucher.isRedeemed) {
      alliesState.lastValidationResult = {
        status: 'already_redeemed',
        code: cleanCode,
        voucher: voucher,
        message: `Atención: El voucher ${cleanCode} ya fue canjeado previamente a las ${voucher.redeemedAt} por ${voucher.redeemedBy || 'Staff'}. No otorgar beneficio duplicado.`
      };
    } else {
      voucher.isRedeemed = true;
      voucher.redeemedAt = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      voucher.redeemedBy = 'Staff Puerta Taquilla #1';
      alliesState.lastValidationResult = {
        status: 'success',
        code: cleanCode,
        voucher: voucher,
        message: `Acceso Concedido: Voucher ${cleanCode} validado con éxito. Beneficio aplicado para ${voucher.leadName} (${maskPhoneNumber(voucher.leadWhatsapp)}).`
      };
      if (typeof showToast === 'function') {
        showToast(`Voucher ${cleanCode} validado y registrado en taquilla`);
      }
    }
  }

  const main = getAlliesMainEl();
  if (main) main.innerHTML = alliesBody();
  renderValidationFeedback();
}

function renderValidationFeedback() {
  const container = document.getElementById('ticketValidationResultContainer');
  if (container && alliesState.lastValidationResult) {
    container.innerHTML = renderTicketValidationResultHtml(alliesState.lastValidationResult);
  }
}

function simulateCapiLeadCapture(campaignId) {
  const campaign = alliesState.campaignsDirA.find(c => c.id === Number(campaignId)) || alliesState.campaignsDirA[0];
  const ally = alliesState.alliesList.find(a => a.id === campaign.allyId);
  const randomVoucherCode = (ally ? ally.code.replace('ALLY-', '').substring(0, 3) : 'VOU') + '-' + Math.floor(1000 + Math.random() * 9000);

  const newCapture = {
    id: Date.now(),
    voucherCode: randomVoucherCode,
    campaignId: campaign.id,
    allyId: ally.id,
    leadName: 'Prospecto Demo ' + Math.floor(Math.random() * 100),
    leadWhatsapp: '+5255' + Math.floor(10000000 + Math.random() * 90000000),
    leadEmail: 'prospecto.' + Math.floor(Math.random() * 1000) + '@marte.store',
    universe: campaign.universe,
    isRedeemed: false,
    redeemedAt: null,
    redeemedBy: null,
    capiScore: 9.80,
    date: new Date().toISOString().split('T')[0]
  };

  alliesState.leadCaptures.unshift(newCapture);
  campaign.leadsCount++;
  if (ally) {
    ally.clearingBalance += ally.leadAcquisitionCost;
    ally.stats.leadsReceived++;
  }

  showToast(`Lead capturado: Voucher ${randomVoucherCode} emitido. Disparo Meta CAPI EMQ 9.8/10 registrado.`);
  const main = getAlliesMainEl();
  if (main) main.innerHTML = alliesBody();
}

function copyCouponCode(code) {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(code).then(() => {
      showToast(`Cupón "${code}" copiado al portapapeles`);
    }).catch(() => {
      showToast(`Cupón: ${code}`);
    });
  } else {
    showToast(`Cupón: ${code}`);
  }
}

function executeClearingSettlement(allyId, type) {
  const ally = alliesState.alliesList.find(a => a.id === Number(allyId));
  if (!ally) return;

  const currentBal = ally.clearingBalance;
  const settlementCode = 'SETTL-' + new Date().toISOString().slice(0, 7).replace('-', '') + '-' + Math.floor(10 + Math.random() * 90);
  const typeLabels = {
    'spei_transfer': 'Transferencia SPEI',
    'in_kind_apparel': 'Canje en Especie (Ropa Interior)',
    'sponsorship_credit': 'Crédito de Patrocinio / Pases VIP'
  };

  const isSpei = (type === 'spei_transfer');
  const settlementStatus = isSpei ? 'scheduled_friday' : 'executed';
  const settlementRef = isSpei
    ? 'PENDIENTE_DISPERSION_SPEI'
    : (type === 'in_kind_apparel' ? `SALIDA_CONVENIO_ALIADO #OC-${settlementCode}` : 'CRÉDITO_PATROCINIO_VENUE');

  const newSettlement = {
    id: Date.now(),
    code: settlementCode,
    allyId: ally.id,
    allyName: ally.name,
    period: '01/05/2026 - 31/05/2026',
    leadsCredit: ally.stats.leadsReceived * ally.leadAcquisitionCost,
    commissionsDebit: ally.stats.commissionEarned,
    netBalance: currentBal,
    settlementType: type,
    typeLabel: typeLabels[type] || type,
    status: settlementStatus,
    reference: settlementRef,
    settledAt: isSpei ? 'Programado Viernes' : new Date().toLocaleString([], { dateStyle: 'short', timeStyle: 'short' })
  };

  alliesState.clearingSettlements.unshift(newSettlement);
  ally.clearingBalance = 0.00;

  // TASK-INT-19: Inyección automática a Cuentas por Pagar en Hub 5 Finanzas
  if (isSpei) {
    const nextFriday = new Date();
    const day = nextFriday.getDay();
    const diff = (5 - day + 7) % 7 || 7;
    nextFriday.setDate(nextFriday.getDate() + diff);
    const dueDateIso = nextFriday.toISOString().slice(0, 10);

    const newBill = {
      id: `bill-${settlementCode.toLowerCase()}`,
      settlementId: newSettlement.id,
      settlementCode: settlementCode,
      allyId: ally.id,
      vendorName: ally.name,
      category: 'ally_commission',
      categoryLabel: 'Comisiones Convenio Aliado',
      invoiceNumber: settlementCode,
      amountMxn: Math.round(Math.abs(currentBal)),
      dueDate: dueDateIso,
      status: 'scheduled_friday',
      paymentMethod: 'spei_transfer',
      recipientClabe: ally.bankClabe || '012180000000000000',
      recipientBank: ally.bankName || 'BBVA Bancomer',
      speiTrackingKey: null
    };

    if (typeof financeState !== 'undefined' && Array.isArray(financeState.vendorBills)) {
      financeState.vendorBills.unshift(newBill);
    }
  }

  if (type === 'in_kind_apparel') {
    showToast(`Liquidación en Especie ejecutada: Asiento inmutable en Kardex SALIDA_CONVENIO_ALIADO registrado para ${ally.name}.`);
  } else if (type === 'spei_transfer') {
    showToast(`Liquidación SPEI sincronizada con Hub 5 Finanzas: Factura ${settlementCode} programada para viernes a ${ally.name}.`);
  } else {
    showToast(`Crédito de patrocinio aplicado para ${ally.name}.`);
  }

  const main = getAlliesMainEl();
  if (main) main.innerHTML = alliesBody();
}

function requestPartnerPayout(type) {
  const ally = alliesState.alliesList.find(a => a.id === alliesState.selectedAllyId) || alliesState.alliesList[0];
  if (ally.clearingBalance >= 0) {
    showToast('No tienes saldo pendiente por cobrar.');
    return;
  }
  executeClearingSettlement(ally.id, type);
}

