// 4. Pestaña: Cámara de Compensación (Clearing House)
function renderAlliesClearingTab(subnavBar) {
  const totalLeadsCredit = alliesState.alliesList.reduce((acc, a) => acc + (a.stats.leadsReceived * a.leadAcquisitionCost), 0);
  const totalCommissionsDebit = alliesState.alliesList.reduce((acc, a) => acc + a.stats.commissionEarned, 0);
  const totalNetBalance = totalLeadsCredit - totalCommissionsDebit;

  return `
    ${subnavBar}

    <!-- 4 KPIs Contextuales del Submódulo 4 (Regla 10) -->
    <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
      <div class="card p-4 bg-white border border-slate-200/80 rounded-xl shadow-sm">
        <div class="flex items-center justify-between text-slate-500 text-xs font-semibold">
          <span>Balance Neto Consolidado</span>
          <button class="section-help-btn" type="button" aria-label="Ayuda de Balance" data-help-title="Balance Neto Global" data-help-desc="Diferencia consolidada entre créditos por leads recibidos y comisiones devengadas por ventas.">?</button>
        </div>
        <div class="text-xl font-bold ${totalNetBalance >= 0 ? 'text-emerald-600' : 'text-amber-600'} mt-1">
          ${totalNetBalance >= 0 ? `+$${totalNetBalance.toFixed(2)} MXN` : `-$${Math.abs(totalNetBalance).toFixed(2)} MXN`}
        </div>
        <span class="text-[11px] text-slate-500 font-medium">${totalNetBalance >= 0 ? 'A favor de Marte Store' : 'Por liquidar a aliados'}</span>
      </div>

      <div class="card p-4 bg-white border border-slate-200/80 rounded-xl shadow-sm">
        <div class="flex items-center justify-between text-slate-500 text-xs font-semibold">
          <span>Crédito Leads Tienda (Dir A)</span>
          <button class="section-help-btn" type="button" aria-label="Ayuda de Crédito" data-help-title="Créditos Dirección A" data-help-desc="Valor acumulado que los aliados reconocen a la tienda por prospectos calificados.">?</button>
        </div>
        <div class="text-xl font-bold text-slate-900 mt-1">$${totalLeadsCredit.toLocaleString()} MXN</div>
        <span class="text-[11px] text-slate-500 font-medium">Reconocimiento contable</span>
      </div>

      <div class="card p-4 bg-white border border-slate-200/80 rounded-xl shadow-sm">
        <div class="flex items-center justify-between text-slate-500 text-xs font-semibold">
          <span>Comisiones Ventas (Dir B)</span>
          <button class="section-help-btn" type="button" aria-label="Ayuda de Comisiones" data-help-title="Comisiones Dirección B" data-help-desc="Comisiones devengadas por los aliados tras compras confirmadas en checkout.">?</button>
        </div>
        <div class="text-xl font-bold text-indigo-600 mt-1">$${totalCommissionsDebit.toLocaleString()} MXN</div>
        <span class="text-[11px] text-slate-500 font-medium">124 órdenes auditadas</span>
      </div>

      <div class="card p-4 bg-white border border-slate-200/80 rounded-xl shadow-sm">
        <div class="flex items-center justify-between text-slate-500 text-xs font-semibold">
          <span>Liquidaciones Cerradas</span>
          <button class="section-help-btn" type="button" aria-label="Ayuda de Liquidaciones" data-help-title="Cierres Contables" data-help-desc="Liquidaciones ejecutadas por SPEI o canje de ropa interior en Kardex este periodo.">?</button>
        </div>
        <div class="text-xl font-bold text-emerald-600 mt-1">${alliesState.clearingSettlements.length} Ejecutadas</div>
        <span class="text-[11px] text-emerald-700 font-medium">100% conciliadas</span>
      </div>
    </div>

    <!-- Tarjeta de Lógica de Liquidación y Fórmula Compensatoria -->
    <div class="p-4 bg-slate-50 border border-slate-200 rounded-xl mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
      <div>
        <span class="text-[10px] font-bold uppercase tracking-wider text-indigo-700 bg-indigo-50 px-2 py-0.5 rounded border border-indigo-200">Lógica de Liquidación Contable</span>
        <h4 class="text-sm font-bold text-slate-900 mt-1">Fórmula de Compensación Cruzada (Cámara RevOps)</h4>
        <p class="text-xs text-slate-600 m-0 font-mono mt-0.5">Saldo Neto = (Prospectos Derivados Dir A &times; Tarifa Lead) &minus; Comisiones Ventas Dir B</p>
      </div>
      <div class="text-xs text-slate-500 bg-white p-2.5 rounded-lg border border-slate-200 shadow-xs max-w-sm">
        <span>Si Saldo Neto &lt; $0.00: <strong>Marte Store liquida al socio</strong> (SPEI o Canje Kardex).</span><br>
        <span>Si Saldo Neto &gt; $0.00: <strong>Crédito a favor de la tienda</strong> por prospectos.</span>
      </div>
    </div>

    <!-- Matriz de Balances Cruzados por Aliado -->
    <div class="card bg-white border border-slate-200 rounded-xl shadow-sm p-5 mb-6">
      <div class="flex items-center justify-between pb-3 border-b border-slate-100 mb-4">
        <div>
          <h3 class="text-sm font-bold text-slate-900">Matriz de Compensación Cruzada por Socio</h3>
          <p class="text-xs text-slate-500 m-0">Compensación auditada de valor de prospectos vs comisiones por prendas vendidas.</p>
        </div>
      </div>

      <div class="overflow-x-auto">
        <table class="clearing-table">
          <thead>
            <tr>
              <th>Aliado / Organización</th>
              <th>Crédito Leads (Dir A)</th>
              <th>Comisión Ventas (Dir B)</th>
              <th>Saldo Neto</th>
              <th>Cuenta CLABE (SPEI)</th>
              <th class="text-right">Liquidación</th>
            </tr>
          </thead>
          <tbody>
            ${alliesState.alliesList.map(a => {
              const leadsVal = a.stats.leadsReceived * a.leadAcquisitionCost;
              const commVal = a.stats.commissionEarned;
              const net = a.clearingBalance;
              return `
                <tr>
                  <td>
                    <strong class="text-slate-900">${a.name}</strong>
                    <div class="text-[11px] text-slate-500">${a.categoryLabel} &bull; ${a.code}</div>
                  </td>
                  <td class="font-mono text-emerald-700 font-semibold">+$${leadsVal.toFixed(2)} (${a.stats.leadsReceived} leads)</td>
                  <td class="font-mono text-indigo-700 font-semibold">&minus;$${commVal.toFixed(2)} (${a.stats.ordersAttributed} ventas)</td>
                  <td>
                    <span class="clearing-balance-tag ${net >= 0 ? 'credit-store' : 'debit-ally'}">
                      ${net >= 0 ? `+$${net.toFixed(2)} (A favor Tienda)` : `-$${Math.abs(net).toFixed(2)} (Por Liquidar)`}
                    </span>
                  </td>
                  <td class="font-mono text-slate-600">${a.bankClabe} (${a.bankName})</td>
                  <td class="text-right">
                    <div class="inline-flex items-center gap-1">
                      <button class="px-2.5 py-1 text-xs font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded shadow-xs" data-action="execute-settlement-btn" data-ally-id="${a.id}" data-type="spei_transfer" title="Liquidar vía SPEI">
                        SPEI
                      </button>
                      <button class="px-2.5 py-1 text-xs font-bold text-amber-900 bg-amber-200 hover:bg-amber-300 rounded shadow-xs" data-action="execute-settlement-btn" data-ally-id="${a.id}" data-type="in_kind_apparel" title="Canje de ropa interior con asiento en Kardex">
                        Canje Ropa
                      </button>
                    </div>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    </div>

    <!-- Historial de Liquidaciones Inmutables -->
    <div class="card bg-white border border-slate-200 rounded-xl shadow-sm p-5">
      <h3 class="text-sm font-bold text-slate-900 mb-3">Historial de Liquidaciones Ejecutadas (Auditoría Contable)</h3>
      <div class="overflow-x-auto">
        <table class="w-full text-xs text-left">
          <thead>
            <tr class="border-b border-slate-200 text-slate-500 font-bold bg-slate-50">
              <th class="p-2.5">Folio Liquidación</th>
              <th class="p-2.5">Socio Comercial</th>
              <th class="p-2.5">Periodo</th>
              <th class="p-2.5">Tipo Modalidad</th>
              <th class="p-2.5">Saldo Compensado</th>
              <th class="p-2.5">Referencia / Asiento Kardex</th>
              <th class="p-2.5">Fecha Cierre</th>
            </tr>
          </thead>
          <tbody class="divide-y divide-slate-100">
            ${alliesState.clearingSettlements.map(s => `
              <tr class="hover:bg-slate-50/80">
                <td class="p-2.5 font-mono font-bold text-slate-900">${s.code}</td>
                <td class="p-2.5 font-semibold text-slate-800">${s.allyName}</td>
                <td class="p-2.5 text-slate-600">${s.period}</td>
                <td class="p-2.5">
                  <span class="settlement-badge ${s.settlementType === 'spei_transfer' ? 'spei' : (s.settlementType === 'in_kind_apparel' ? 'inkind' : 'sponsorship')}">
                    ${s.typeLabel}
                  </span>
                  ${s.status === 'scheduled_friday' ? `
                    <span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-amber-100 text-amber-800 border border-amber-300 ml-1.5 inline-block">
                      Programada Viernes (Hub 5)
                    </span>
                  ` : (s.status === 'executed' && s.settlementType === 'spei_transfer' ? `
                    <span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-800 border border-emerald-300 ml-1.5 inline-block">
                      Liquidado SPEI
                    </span>
                  ` : '')}
                </td>
                <td class="p-2.5 font-mono font-bold ${s.netBalance >= 0 ? 'text-emerald-700' : 'text-slate-900'}">$${Math.abs(s.netBalance).toFixed(2)}</td>
                <td class="p-2.5 font-mono text-indigo-700">${s.reference}</td>
                <td class="p-2.5 text-slate-500">${s.settledAt}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    </div>
  `;
}

// 5. Pestaña / Pantalla: Partner Portal (Extranet de Aliados)
function renderAlliesPartnerPortalTab(subnavBar) {
  const ally = alliesState.alliesList.find(a => a.id === alliesState.selectedAllyId) || alliesState.alliesList[0];
  const allyLeads = alliesState.leadCaptures.filter(l => l.allyId === ally.id);
  const allyCoupon = alliesState.couponsDirB.find(c => c.allyId === ally.id) || alliesState.couponsDirB[0];
  const trackingUrl = `https://marte.store/?ref=${ally.code}&utm_source=${allyCoupon.utmSource}&utm_campaign=partner_2026`;

  // Generamos un QR limpio para flyers
  const qrSvg = (typeof generateQrCodeSvg === 'function') ? generateQrCodeSvg(trackingUrl) : `
    <svg viewBox="0 0 120 120" width="120" height="120">
      <rect width="120" height="120" fill="#f8fafc"/>
      <rect x="15" y="15" width="30" height="30" fill="#0f172a"/>
      <rect x="20" y="20" width="20" height="20" fill="#ffffff"/>
      <rect x="25" y="25" width="10" height="10" fill="#0f172a"/>
      <rect x="75" y="15" width="30" height="30" fill="#0f172a"/>
      <rect x="80" y="20" width="20" height="20" fill="#ffffff"/>
      <rect x="85" y="25" width="10" height="10" fill="#0f172a"/>
      <rect x="15" y="75" width="30" height="30" fill="#0f172a"/>
      <rect x="20" y="80" width="20" height="20" fill="#ffffff"/>
      <rect x="25" y="85" width="10" height="10" fill="#0f172a"/>
      <rect x="55" y="55" width="12" height="12" fill="#0f172a"/>
      <rect x="75" y="75" width="15" height="15" fill="#0f172a"/>
    </svg>
  `;

  return `
    ${subnavBar}

    <!-- Selector de Aliado y Banner de Acceso por Token -->
    <div class="p-4 bg-indigo-950 text-white rounded-xl shadow-md mb-6 space-y-3">
      <div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div class="flex items-center gap-3">
          <div class="w-10 h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-bold text-base shadow">
            ${ally.name.substring(0, 2).toUpperCase()}
          </div>
          <div>
            <div class="flex items-center gap-2">
              <h2 class="text-base font-bold text-white m-0">${ally.name}</h2>
              <span class="px-2 py-0.5 rounded text-[10px] font-bold bg-indigo-800 text-indigo-200 uppercase">${ally.categoryLabel}</span>
              ${alliesState.tokenRestrictedMode ? `
                <span class="px-2 py-0.5 rounded text-[10px] font-bold bg-emerald-900 text-emerald-300 border border-emerald-700">Token Activo (Solo Lectura)</span>
              ` : ''}
            </div>
            <p class="text-xs text-indigo-300 m-0">Token Extranet: <span class="font-mono text-white">${ally.portalToken}</span></p>
          </div>
        </div>
        <div class="flex items-center gap-2">
          ${!alliesState.tokenRestrictedMode ? `
            <span class="text-xs text-indigo-200">Ver portal como:</span>
            <select class="bg-indigo-900 border border-indigo-700 text-white text-xs rounded-lg px-2.5 py-1.5 outline-none font-medium cursor-pointer" data-action="change-partner-select">
              ${alliesState.alliesList.map(a => `
                <option value="${a.id}" ${a.id === ally.id ? 'selected' : ''}>${a.name}</option>
              `).join('')}
            </select>
          ` : `
            <span class="px-2.5 py-1 rounded bg-indigo-900 text-indigo-200 text-xs font-semibold border border-indigo-700">Restringido a ${ally.name}</span>
          `}
        </div>
      </div>

      <!-- Enlace Directo por Token Criptográfico (Sin Password) -->
      <div class="pt-3 border-t border-indigo-900 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 text-xs">
        <div class="flex items-center gap-2 overflow-hidden">
          <span class="text-[11px] font-bold uppercase text-indigo-300 shrink-0">Enlace Seguro:</span>
          <span class="font-mono text-indigo-200 bg-indigo-900/80 px-2 py-0.5 rounded border border-indigo-800 text-[11px] truncate">https://marte.store/portal/aliado/${ally.portalToken}</span>
        </div>
        <div class="flex items-center gap-2 shrink-0">
          <button class="px-2.5 py-1 text-xs font-bold text-white bg-indigo-600 hover:bg-indigo-500 rounded shadow-xs transition-colors cursor-pointer" data-action="copy-portal-url" data-url="https://marte.store/portal/aliado/${ally.portalToken}">
            Copiar Enlace
          </button>
          ${!alliesState.tokenRestrictedMode ? `
            <button class="px-2.5 py-1 text-xs font-bold text-indigo-300 bg-indigo-900 hover:bg-indigo-800 border border-indigo-700 rounded shadow-xs transition-colors cursor-pointer" data-action="simulate-token-login" data-token="${ally.portalToken}">
              Entrar vía Token
            </button>
          ` : ''}
        </div>
      </div>
    </div>

    <!-- 4 KPIs del Partner Portal (Regla 10) -->
    <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
      <div class="card p-4 bg-white border border-slate-200/80 rounded-xl shadow-sm">
        <div class="flex items-center justify-between text-slate-500 text-xs font-semibold">
          <span>Mis Comisiones Ganadas</span>
          <button class="section-help-btn" type="button" aria-label="Ayuda de Comisiones" data-help-title="Comisiones Ganadas" data-help-desc="Monto acumulado por compras de tus clientes usando tu cupón de ${ally.commissionRate}%.">?</button>
        </div>
        <div class="text-xl font-bold text-indigo-600 mt-1">$${ally.stats.commissionEarned.toLocaleString()} MXN</div>
        <span class="text-[11px] text-slate-500 font-medium">${ally.commissionRate}% por cada venta</span>
      </div>

      <div class="card p-4 bg-white border border-slate-200/80 rounded-xl shadow-sm">
        <div class="flex items-center justify-between text-slate-500 text-xs font-semibold">
          <span>Ventas Referidas</span>
          <button class="section-help-btn" type="button" aria-label="Ayuda de Ventas" data-help-title="Ventas Totales" data-help-desc="Facturación total que tu comunidad ha comprado en Marte Store.">?</button>
        </div>
        <div class="text-xl font-bold text-slate-900 mt-1">$${ally.stats.gmvAttributed.toLocaleString()} MXN</div>
        <span class="text-[11px] text-slate-500 font-medium">${ally.stats.ordersAttributed} pedidos entregados</span>
      </div>

      <div class="card p-4 bg-white border border-slate-200/80 rounded-xl shadow-sm">
        <div class="flex items-center justify-between text-slate-500 text-xs font-semibold">
          <span>Leads en mi Evento / Puerta</span>
          <button class="section-help-btn" type="button" aria-label="Ayuda de Leads" data-help-title="Leads de Taquilla" data-help-desc="Asistentes registrados en Marte Store con beneficio para tu evento.">?</button>
        </div>
        <div class="text-xl font-bold text-emerald-600 mt-1">${allyLeads.length} Asistentes</div>
        <span class="text-[11px] text-emerald-700 font-medium">${allyLeads.filter(l => l.isRedeemed).length} canjeados en puerta</span>
      </div>

      <div class="card p-4 bg-white border border-slate-200/80 rounded-xl shadow-sm">
        <div class="flex items-center justify-between text-slate-500 text-xs font-semibold">
          <span>Saldo Disponible para Cobro</span>
          <button class="section-help-btn" type="button" aria-label="Ayuda de Cobro" data-help-title="Saldo Neto" data-help-desc="Monto neto que puedes retirar por transferencia SPEI o canjear por ropa interior.">?</button>
        </div>
        <div class="text-xl font-bold ${ally.clearingBalance < 0 ? 'text-emerald-600' : 'text-slate-900'} mt-1">
          $${Math.abs(ally.clearingBalance).toFixed(2)} MXN
        </div>
        <span class="text-[11px] text-slate-500 font-medium">${ally.clearingBalance < 0 ? 'Listo para retirar' : 'Al corriente'}</span>
      </div>
    </div>

    <!-- DOS COLUMNAS OPERATIVAS: Validador en Taquilla vs Material de Difusión -->
    <div class="grid grid-cols-1 lg:grid-cols-12 gap-6 mb-6">
      
      <!-- Columna Izquierda: Validador en Taquilla / Puerta (TASK-ALY-05) -->
      <div class="lg:col-span-7">
        <div class="ticket-validator-box">
          <div class="flex items-center justify-between pb-3 border-b border-slate-800 mb-4">
            <div class="flex items-center gap-2">
              <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="m9 12 2 2 4-4"/></svg>
              <h3 class="text-sm font-bold text-white uppercase tracking-wider m-0">Validador de Taquilla / Acceso</h3>
            </div>
            <span class="px-2 py-0.5 rounded text-[10px] font-bold bg-emerald-950 text-emerald-300 border border-emerald-800">Cámara Activa</span>
          </div>

          <p class="text-xs text-slate-300 mb-4">
            Ingresa el código alfanumérico del voucher mostrado por el cliente en su smartphone para confirmar su descuento en cover o beneficio.
          </p>

          <form data-action="validate-ticket-form" class="space-y-3">
            <div class="flex gap-2">
              <input type="text" class="ticket-input" id="ticketVoucherInput" placeholder="EJ. PAR-7821" autocomplete="off" autofocus>
              <button type="submit" class="px-5 py-3 text-sm font-bold text-white bg-indigo-600 hover:bg-indigo-500 rounded-lg transition-all shadow-md flex items-center gap-2 shrink-0 cursor-pointer">
                <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
                <span>Validar</span>
              </button>
            </div>
          </form>

          <div id="ticketValidationResultContainer">
            ${renderTicketValidationResultHtml(alliesState.lastValidationResult)}
          </div>

          <!-- Bitácora de accesos validados en esta sesión y Exportación CSV -->
          <div class="mt-6 pt-4 border-t border-slate-800">
            <div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 text-xs text-slate-400 mb-3">
              <div class="flex items-center gap-2">
                <span>Vouchers verificados en taquilla:</span>
                <span class="px-1.5 py-0.5 rounded bg-slate-800 text-slate-200 font-bold">${allyLeads.filter(l => l.isRedeemed).length} canjeados</span>
              </div>
              <button class="door-list-export-btn" data-action="export-door-list-csv" data-ally-id="${ally.id}">
                <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
                <span>Descargar CSV Taquilla</span>
              </button>
            </div>
            <div class="mb-3 flex items-center justify-between">
              <span class="data-masking-chip">
                <svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2"><rect width="18" height="11" x="3" y="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>
                <span>Data Masking Activo: Teléfonos protegidos (ej. 55 **** 1290)</span>
              </span>
              <span class="text-[10px] text-slate-500">BD protegida hasta fecha de corte</span>
            </div>
            <div class="space-y-1.5 max-h-48 overflow-y-auto pr-1">
              ${allyLeads.filter(l => l.isRedeemed).map(l => `
                <div class="p-2 bg-slate-900/90 rounded-lg flex items-center justify-between text-xs border border-slate-800">
                  <div class="flex items-center gap-2">
                    <span class="font-mono font-bold text-emerald-400">${l.voucherCode}</span>
                    <span class="text-slate-300">${l.leadName}</span>
                    <span class="font-mono text-[11px] text-slate-500">(${maskPhoneNumber(l.leadWhatsapp)})</span>
                  </div>
                  <span class="text-[11px] text-slate-500">${l.redeemedAt}</span>
                </div>
              `).join('')}
            </div>
          </div>
        </div>
      </div>

      <!-- Columna Derecha: Material de Difusión y Código QR SVG -->
      <div class="lg:col-span-5 space-y-4">
        <!-- Cupón y Enlace -->
        <div class="card bg-white border border-slate-200 rounded-xl p-5 shadow-sm">
          <h3 class="text-sm font-bold text-slate-900 mb-3">Tus Herramientas de Difusión</h3>
          
          <div class="space-y-3">
            <div>
              <label class="text-[11px] font-bold text-slate-500 uppercase block mb-1">Tu Cupón Exclusivo (15% OFF):</label>
              <div class="flex items-center gap-2">
                <button class="coupon-copy-chip text-sm w-full justify-between" data-action="copy-coupon-btn" data-code="${allyCoupon.couponCode}">
                  <span class="font-mono font-bold text-indigo-700">${allyCoupon.couponCode}</span>
                  <span class="text-[10px] font-bold text-indigo-600 uppercase">Copiar Cupón</span>
                </button>
              </div>
            </div>

            <div>
              <label class="text-[11px] font-bold text-slate-500 uppercase block mb-1">Enlace de Afiliado (UTM Tracking):</label>
              <div class="p-2 bg-slate-50 border border-slate-200 rounded-lg flex items-center justify-between gap-2 text-xs">
                <span class="font-mono text-slate-700 truncate">${trackingUrl}</span>
                <button class="px-2 py-1 text-[11px] font-bold text-slate-700 bg-white border border-slate-300 rounded shadow-xs hover:bg-slate-100 shrink-0" data-action="copy-coupon-btn" data-code="${trackingUrl}">
                  Copiar
                </button>
              </div>
            </div>
          </div>
        </div>

        <!-- Código QR para Flyers e Historias -->
        <div class="card bg-white border border-slate-200 rounded-xl p-5 shadow-sm text-center">
          <h3 class="text-sm font-bold text-slate-900 mb-1">Código QR para Flyers Impresos</h3>
          <p class="text-xs text-slate-500 mb-3">Imprime este código en la entrada o flyers de tu fiesta para acreditar comisiones.</p>
          
          <div class="qr-preview-box mx-auto mb-3">
            ${qrSvg}
          </div>
          <span class="text-[11px] text-slate-400 font-mono block">Vector SVG Alta Resolución</span>
        </div>

        <!-- Consola de Retiros y Canje -->
        <div class="card bg-white border border-slate-200 rounded-xl p-5 shadow-sm">
          <h3 class="text-sm font-bold text-slate-900 mb-1">Retiro de Saldo & Canje</h3>
          <p class="text-xs text-slate-500 mb-3">Tu saldo se deposita a tu cuenta <strong class="text-slate-700">${ally.bankName}</strong> (CLABE: <span class="font-mono text-slate-700">***${ally.bankClabe.slice(-4)}</span>).</p>
          
          ${alliesState.clearingSettlements.some(s => s.allyId === ally.id && s.status === 'scheduled_friday') ? `
            <div class="mb-3 p-2.5 bg-amber-50 border border-amber-200 rounded-lg text-xs text-amber-900">
              <div class="font-bold flex items-center gap-1.5">
                <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                <span>Liquidación Programada para Viernes</span>
              </div>
              <p class="text-[11px] text-amber-800 mt-1 mb-0">
                Tu solicitud está en cola de dispersión SPEI en Finanzas (Hub 5). Recibirás tu comprobante bancario al corte.
              </p>
            </div>
          ` : ''}

          <div class="grid grid-cols-2 gap-2">
            <button class="px-3 py-2 text-xs font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg transition-colors shadow-xs" data-action="request-payout-spei">
              Solicitar SPEI
            </button>
            <button class="px-3 py-2 text-xs font-bold text-amber-900 bg-amber-200 hover:bg-amber-300 rounded-lg transition-colors shadow-xs" data-action="request-payout-apparel">
              Canje de Ropa
            </button>
          </div>
        </div>
      </div>

    </div>
  `;
}

// Event Delegation para Hub 7
document.addEventListener('click', (e) => {
  // Conmutador de Modo Admin vs Partner
  const modeBtn = e.target.closest('[data-action="switch-allies-mode"]');
  if (modeBtn) {
    e.preventDefault();
    switchAlliesMode(modeBtn.dataset.mode);
    return;
  }

  // Pestañas de Subnavegación Admin
  const tabBtn = e.target.closest('[data-action="switch-allies-tab"]');
  if (tabBtn) {
    e.preventDefault();
    switchAlliesTab(tabBtn.dataset.tab);
    return;
  }

  // Filtro de Universo
  const univBtn = e.target.closest('[data-action="filter-allies-universe"]');
  if (univBtn) {
    e.preventDefault();
    filterAlliesUniverse(univBtn.dataset.universe);
    return;
  }

  // Filtro de Categoría
  const catBtn = e.target.closest('[data-action="filter-allies-category"]');
  if (catBtn) {
    e.preventDefault();
    filterAlliesCategory(catBtn.dataset.category);
    return;
  }

  // Abrir Partner Portal para un Aliado específico
  const openPortalBtn = e.target.closest('[data-action="open-partner-portal-for-ally"]');
  if (openPortalBtn) {
    e.preventDefault();
    alliesState.selectedAllyId = Number(openPortalBtn.dataset.allyId);
    switchAlliesMode('partner');
    return;
  }

  // Copiar código de cupón
  const copyBtn = e.target.closest('[data-action="copy-coupon-btn"]');
  if (copyBtn) {
    e.preventDefault();
    copyCouponCode(copyBtn.dataset.code);
    return;
  }

  // Simular Captura de Lead CAPI
  const simCapiBtn = e.target.closest('[data-action="simulate-capi-lead-btn"]');
  if (simCapiBtn) {
    e.preventDefault();
    simulateCapiLeadCapture(simCapiBtn.dataset.campaignId);
    return;
  }

  // Ejecutar Liquidación desde Admin
  const settlBtn = e.target.closest('[data-action="execute-settlement-btn"]');
  if (settlBtn) {
    e.preventDefault();
    executeClearingSettlement(settlBtn.dataset.allyId, settlBtn.dataset.type);
    return;
  }

  // Solicitar Retiro SPEI desde Partner Portal
  const payoutSpeiBtn = e.target.closest('[data-action="request-payout-spei"]');
  if (payoutSpeiBtn) {
    e.preventDefault();
    requestPartnerPayout('spei_transfer');
    return;
  }

  // Solicitar Canje de Ropa desde Partner Portal
  const payoutApparelBtn = e.target.closest('[data-action="request-payout-apparel"]');
  if (payoutApparelBtn) {
    e.preventDefault();
    requestPartnerPayout('in_kind_apparel');
    return;
  }

  // Copiar Enlace Seguro por Token
  const copyUrlBtn = e.target.closest('[data-action="copy-portal-url"]');
  if (copyUrlBtn) {
    e.preventDefault();
    copyCouponCode(copyUrlBtn.dataset.url);
    return;
  }

  // Simular Acceso Directo por Token Criptografico (Sin Password)
  const tokenLoginBtn = e.target.closest('[data-action="simulate-token-login"]');
  if (tokenLoginBtn) {
    e.preventDefault();
    accessPortalByToken(tokenLoginBtn.dataset.token);
    return;
  }

  // Salir de Modo Restringido por Token
  const exitTokenBtn = e.target.closest('[data-action="exit-token-restricted"]');
  if (exitTokenBtn) {
    e.preventDefault();
    exitTokenRestrictedMode();
    return;
  }

  // Descargar Lista de Asistentes en CSV para Taquilla
  const exportCsvBtn = e.target.closest('[data-action="export-door-list-csv"]');
  if (exportCsvBtn) {
    e.preventDefault();
    exportAlliesDoorListCsv(exportCsvBtn.dataset.allyId);
    return;
  }
});

// Event Listener para submit del validador de taquilla
document.addEventListener('submit', (e) => {
  const form = e.target.closest('[data-action="validate-ticket-form"]');
  if (form) {
    e.preventDefault();
    const input = document.getElementById('ticketVoucherInput');
    if (input) {
      validateTicketVoucher(input.value);
    }
  }
});

// Selector de aliado en Partner Portal & Carga de Factura Courier CSV
document.addEventListener('change', (e) => {
  const select = e.target.closest('[data-action="change-partner-select"]');
  if (select) {
    selectPartnerPortalAlly(select.value);
    return;
  }
  if (e.target && e.target.id === 'carrierInvoiceCsvInput') {
    const file = e.target.files && e.target.files[0];
    if (file) {
      loadSampleCarrierInvoice();
      showToast(`Archivo "${file.name}" cargado y auditado con éxito contra cubicaje de rampa.`);
    }
    return;
  }
});



